var PATH_BOOK_HIST = {"subject": "历史", "book": "中外历史纲要（上）", "version": "统编版", "chapters": [{"no": "第一单元", "title": "从中华文明起源到秦汉统一多民族封建国家的建立与巩固", "units": ["u_hist_1", "u_hist_2", "u_hist_3", "u_hist_4"]}, {"no": "第二单元", "title": "三国两晋南北朝的民族交融与隋唐统一多民族封建国家的发展", "units": ["u_hist_5", "u_hist_6", "u_hist_7", "u_hist_8"]}], "order": ["u_hist_1", "u_hist_2", "u_hist_3", "u_hist_4", "u_hist_5", "u_hist_6", "u_hist_7", "u_hist_8"], "nodes": {"hist_h001": {"name": "石器时代与中华文明的起源", "sec": 1, "secTitle": "中华文明的起源与早期国家", "page": null, "desc": "元谋人、北京人到仰韶、河姆渡：文明起源的多元一体格局。", "criteria": ["能复述本节核心史实与时间", "能看懂案例史料的解读过程", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清史料依据"], "diag": null, "pre": [], "next": ["hist_h002"], "content": {"advance": {"a": "多元：不同地区独立起源、各具特色（黄河、长江流域并存）；一体：在发展中相互交流融合，逐渐形成以中原为核心的整体。判断依据是遗址的分布范围与文化交流的证据（如各地陶器、玉器风格的相互影响）。", "kind": "self", "q": "「多元一体」是中华文明起源的总体特征。请分别解释「多元」和「一体」的含义，并各说一个判断依据。"}, "apply": [{"ans": 1, "opts": ["仰韶文化", "河姆渡文化", "龙山文化", "红山文化"], "q": "种植水稻、住干栏式房屋的文化遗存是（ ）", "why": "河姆渡文化位于长江下游，已种植水稻；仰韶文化在黄河中游，种植粟。"}], "basics": [{"ans": 0, "opts": ["元谋人", "北京人", "山顶洞人", "河姆渡人"], "q": "我国境内目前已确认的最早古人类是（ ）", "why": "元谋人距今约 170 万年，是我国境内已知最早的古人类。"}, {"ans": 2, "opts": ["采集渔猎为主，过群居生活", "已经从事原始农业", "开始饲养家畜、制作陶器", "出现贫富分化"], "q": "北京人所处旧石器时代的生活特点是（ ）", "why": "旧石器时代以采集渔猎为生；农业、家畜、陶器都是新石器时代的标志。"}], "case": {"a": "说明新石器时代南北都已有定居农业文明，中华文明起源呈现多地并起的「多元」格局。", "hints": ["先定位：两个遗址分属黄河、长江两大流域。", "再看作物：粟是北方旱作，水稻是南方水田农业。", "结论方向：文明起源不是单一起源。"], "q": "材料：仰韶文化遗址出土大量粟的遗存；河姆渡文化遗址出土稻谷遗存和干栏式建筑。两则材料共同说明了什么？", "steps": ["仰韶在黄河中游，以粟作农业为基础；河姆渡在长江下游，以稻作农业为基础。", "两地相距遥远、作物体系不同，说明农业文明在南北多地 independently 兴起。", "结合龙山文化时期各地文化交流加强的事实，可得出「多元起源、走向一体」的结论。"], "talk": ["史料题三步：读材料（时间、地点、关键物）→提信息→扣结论。先分开解读两则，再谈共同指向。"], "title": "案例：两则材料读出「多元一体」"}, "intro": "中华文明不是从一个地方冒出来的。==从旧石器时代的元谋人、北京人，到新石器时代遍布南北的文化遗存，中华文明起源的总体特征是「多元一体」。==这一节先把时间和地点钉牢：谁在哪、种什么、用什么。", "learn": [{"h": "旧石器时代：元谋人与北京人", "p": "**元谋人**距今约 **170 万年**，是我国境内已知最早的古人类；**北京人**距今约 **70 万—20 万年**，过着群居生活，以采集、渔猎为生，已经学会使用**天然火**。\n\n这一时期用**打制石器**，生产水平低，人类对自然依赖极强。"}, {"h": "新石器时代：农业革命", "p": "距今约 **1 万年**起进入新石器时代：使用**磨制石器**，从事**原始农业**、饲养家畜、制作陶器，生活逐渐稳定（定居）。\n\n代表遗存要成对记：黄河中游的**仰韶文化**（种植**粟**、彩陶）、黄河下游的**大汶口文化**、长江下游的**河姆渡文化**（种植**水稻**、干栏式房屋）。"}, {"h": "多元一体格局形成", "p": "距今约 **5000 年**进入文明起源加速期，龙山文化时代邦国林立（「万邦」时代），各地文化交流融合，逐渐形成以**中原为核心**的格局。\n\n==记住空间分布：不同流域的文化各具特色，这是「多元」；它们在交流中走向融合，这是「一体」。=="}], "pitfalls": ["仰韶（粟）与河姆渡（水稻）的流域和作物对错位。", "把旧石器时代写成已有农业（农业是新石器时代的标志）。"], "svg": "<rect x='20' y='25' width='150' height='34' rx='6' fill='#e0f2fe'/><text x='95' y='47' text-anchor='middle' font-size='12'>黄河流域：仰韶（粟）</text><rect x='200' y='25' width='150' height='34' rx='6' fill='#e0f2fe'/><text x='275' y='47' text-anchor='middle' font-size='12'>长江流域：河姆渡（稻）</text><rect x='110' y='85' width='150' height='34' rx='6' fill='#dbeafe'/><text x='185' y='107' text-anchor='middle' font-size='12'>多元一体 · 中原核心</text><line x1='120' y1='59' x2='160' y2='85' stroke='#94a3b8'/><line x1='250' y1='59' x2='210' y2='85' stroke='#94a3b8'/>", "svgCap": "文明起源格局：南北多点起源，在交流中走向一体。"}, "video": {"bvid": "BV1Uz4y1p752", "p": 1, "t": "第1课：中华文明的起源与早期国家（源史社会）", "dur": "40:14", "from": 0, "vtop": ["文明起源的特征是多元一体：多地起源、走向融合、中原为核心。", "仰韶种粟（黄河）、河姆渡种稻（长江），遗址要成对记。", "早期国家靠血缘组织：世袭、分封、宗法都是家国一体。"], "vsum": "第1课跨度最大：旧石器时代元谋人（约170万年）、北京人（会用火）打底，新石器时代农业革命后，仰韶（黄河中游、粟、彩陶）、大汶口、河姆渡（长江下游、水稻）==多点开花，形成多元一体格局==。进入早期国家阶段：夏行**世袭制**（二里头遗址），商有甲骨文与内外服制，西周靠**分封制**、**宗法制**（核心是**嫡长子继承制**）、礼乐制组织国家——共同特征是神权与王权结合、血缘为纽带、家国一体、地方控制松散。视频为源史社会纲要上第1课精讲（40:14）。\n易错提醒：宗法制的核心要答嫡长子继承制，只答「血缘关系」太笼统、不得分。", "vtech": ["看到两则不同地域的材料 → 先分别提取地点与关键物，再问「共同指向什么格局」。", "看到遗址配对题 → 按流域锁定：黄河—仰韶—粟，长江—河姆渡—稻。", "看到「早期国家特征」设问 → 从神权、血缘、集权程度、地方控制四点逐项找。"], "vgaokao": []}}, "hist_h002": {"name": "早期国家：夏商西周与分封宗法", "sec": 2, "secTitle": "中华文明的起源与早期国家", "page": null, "desc": "世袭制、二里头、甲骨文、内外服制、分封制与宗法制——家国同构的早期国家。", "criteria": ["能复述本节核心史实与时间", "能看懂案例史料的解读过程", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清史料依据"], "diag": null, "pre": ["hist_h001"], "next": ["hist_h003"], "content": {"advance": {"a": "因为它们都以血缘关系为纽带维系统治：分封按血缘亲疏分配权力，宗法按血缘嫡庶确定等级，体现了早期国家「家国一体」的特征。", "kind": "self", "q": "为什么说分封制、宗法制体现了「家国同构」（家国一体）的特点？"}, "apply": [{"ans": 1, "opts": ["禅让制", "世袭制", "察举制", "郡县制"], "q": "夏朝开始，王位传承由公天下变为「家天下」，依靠的是（ ）", "why": "禹死后启继位，王位世袭制取代禅让制。"}, {"ans": 2, "opts": ["郡县制", "内外服制", "分封制", "行省制"], "q": "商朝对地方的统治方式主要是（ ）", "why": "商朝实行内外服制：王畿为内服，方国部族为外服。"}], "basics": [{"ans": 0, "opts": ["分封制", "宗法制", "礼乐制", "郡县制"], "q": "西周把王族、贵族分派到各地建立诸侯国的制度是（ ）", "why": "分封制：周天子封诸侯，诸侯在封国内世袭统治并承担义务。"}, {"ans": 1, "opts": ["财产平均分配", "嫡长子继承制", "民主推举", "年长者优先但不分嫡庶"], "q": "宗法制的核心是（ ）", "why": "宗法制以嫡长子继承制为核心，区分大宗小宗、凝聚血缘等级。"}], "case": {"a": "说明西周国家权力与血缘宗法合为一体，政治关系以血缘亲疏定等级（家国同构）；同时也说明地方控制仍较松散，诸侯有相对独立性。", "hints": ["抓住材料里的两组词：一边是亲属称谓，一边是政治等级。", "再想一步：诸侯「有相对独立性」反映了早期国家什么特点？"], "q": "材料（据教材整理）：西周初年，周天子分封众多同姓诸侯，诸侯对天子以「伯父」「叔父」等亲属称谓相称；同时诸侯在封国内可世袭、设官、建军。材料说明了什么？", "steps": ["亲属称谓出现在政治场合，说明血缘关系与政治等级重合。", "这正是宗法制与分封制结合形成的「家国同构」结构。", "诸侯世袭并自设官军，说明早期国家的地方控制松散、权力未高度集中。"], "talk": ["材料里出现亲属称谓+政治行为，就是在提示「血缘与王权结合」，直接往家国同构上扣。"], "title": "案例：从称谓看家国同构"}, "intro": "国家出现了，靠什么组织？夏商周三代的答案是**血缘**。==早期国家的共同特征是：神权与王权结合、以血缘为纽带、家国一体、地方控制松散。==这一节的三个制度（世袭、分封、宗法）都要挂回这条总特征。", "learn": [{"h": "夏：世袭制与二里头", "p": "约**公元前 2070 年**禹建夏朝，**世袭制**取代禅让制（家天下）。河南偃师**二里头遗址**被认为是夏都遗存，出土宫殿、青铜器，是探索夏文化的关键证据。夏的统治：王畿直接统治，周边靠控制部族间接统治。"}, {"h": "商：甲骨文与内外服", "p": "约**公元前 1600 年**汤建商朝。文化名片是**甲骨文**（成熟的文字）和青铜铸造。地方统治实行**内外服制**：内服是王畿地区，外服是受商王控制的方国、部族。\n\n神权色彩浓厚：大事占卜问神，王权与神权紧密结合。"}, {"h": "西周：分封、宗法、礼乐", "p": "**公元前 1046 年**武王伐纣建周。**分封制**：把王族、功臣、先代贵族分封到各地建国，诸侯承担服从命令、镇守疆土、随从作战、缴纳贡赋、朝觐述职等义务。**宗法制**：以**嫡长子继承制**为核心，用血缘亲疏定等级。**礼乐制**：用礼乐规范贵族行为等级。\n\n==三件套的共同纽带是血缘：分封封的是亲族，宗法分的是嫡庶，礼乐定的是亲疏等级。=="}], "pitfalls": ["分封制与郡县制混淆（郡县是秦朝的，本课还没有）。", "宗法制核心答成「血缘关系」太笼统——要答嫡长子继承制。"], "svg": "<rect x='130' y='12' width='110' height='30' rx='6' fill='#2563eb'/><text x='185' y='32' text-anchor='middle' font-size='13' fill='#fff'>周天子</text><rect x='15' y='75' width='100' height='30' rx='6' fill='#e0f2fe'/><text x='65' y='95' text-anchor='middle' font-size='12'>诸侯（分封）</text><rect x='140' y='75' width='100' height='30' rx='6' fill='#e0f2fe'/><text x='190' y='95' text-anchor='middle' font-size='12'>卿大夫</text><rect x='265' y='75' width='100' height='30' rx='6' fill='#e0f2fe'/><text x='315' y='95' text-anchor='middle' font-size='12'>士</text><text x='185' y='130' text-anchor='middle' font-size='12' fill='#dc2626'>纽带：血缘（宗法） · 规范：礼乐</text><line x1='150' y1='42' x2='70' y2='75' stroke='#94a3b8'/><line x1='185' y1='42' x2='190' y2='75' stroke='#94a3b8'/><line x1='220' y1='42' x2='310' y2='75' stroke='#94a3b8'/>", "svgCap": "西周统治结构：天子—诸侯—卿大夫—士，靠血缘与礼乐维系。"}, "video": {"bvid": "BV1Uz4y1p752", "p": 1, "t": "第1课：中华文明的起源与早期国家（源史社会）", "dur": "40:14", "from": 0, "vtop": ["文明起源的特征是多元一体：多地起源、走向融合、中原为核心。", "仰韶种粟（黄河）、河姆渡种稻（长江），遗址要成对记。", "早期国家靠血缘组织：世袭、分封、宗法都是家国一体。"], "vsum": "第1课跨度最大：旧石器时代元谋人（约170万年）、北京人（会用火）打底，新石器时代农业革命后，仰韶（黄河中游、粟、彩陶）、大汶口、河姆渡（长江下游、水稻）==多点开花，形成多元一体格局==。进入早期国家阶段：夏行**世袭制**（二里头遗址），商有甲骨文与内外服制，西周靠**分封制**、**宗法制**（核心是**嫡长子继承制**）、礼乐制组织国家——共同特征是神权与王权结合、血缘为纽带、家国一体、地方控制松散。视频为源史社会纲要上第1课精讲（40:14）。\n易错提醒：宗法制的核心要答嫡长子继承制，只答「血缘关系」太笼统、不得分。", "vtech": ["看到两则不同地域的材料 → 先分别提取地点与关键物，再问「共同指向什么格局」。", "看到遗址配对题 → 按流域锁定：黄河—仰韶—粟，长江—河姆渡—稻。", "看到「早期国家特征」设问 → 从神权、血缘、集权程度、地方控制四点逐项找。"], "vgaokao": []}}, "hist_h003": {"name": "春秋战国的纷争与变法运动", "sec": 3, "secTitle": "诸侯纷争与变法运动", "page": null, "desc": "铁器牛耕→井田瓦解→变法潮流；商鞅变法的内容与富国强兵的作用。", "criteria": ["能复述本节核心史实与时间", "能看懂案例史料的解读过程", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清史料依据"], "diag": null, "pre": ["hist_h002"], "next": ["hist_h004", "hist_h005"], "content": {"advance": {"a": "相同：都顺应了从奴隶制向封建制转型的趋势，都涉及土地与赋税改革。不同（以商鞅变法为例）：商鞅变法最彻底——不仅改经济，还改政治（县制、军功爵）与社会组织（什伍连坐），且以法家思想为指导、以富国强兵为直接目标。", "kind": "self", "q": "商鞅变法与各国变法（如吴起变法）相比，相同点和不同点各说一条。"}, "apply": [{"ans": 1, "opts": ["井田制得到巩固", "封建土地私有制逐步确立", "奴隶制土地国有制加强", "土地全部收归国家平均分配"], "q": "春秋战国时期，各国「废井田、开阡陌」的实质是（ ）", "why": "承认土地私有，封建土地私有制确立。"}, {"ans": 2, "opts": ["周天子权力大大加强", "贵族垄断政权的局面被强化", "新兴地主阶级势力增强", "农民与地主的矛盾消失"], "q": "军功爵制的实行，最直接的影响是（ ）", "why": "按军功授爵，平民可凭战功上升，冲击世卿世禄、壮大地主阶级。"}], "basics": [{"ans": 0, "opts": ["商鞅变法", "管仲改革", "吴起变法", "北魏孝文帝改革"], "q": "使秦国后来居上、为统一六国奠定基础的变法是（ ）", "why": "商鞅变法（前356年起）使秦国富强，是秦统一的关键主观条件。"}, {"ans": 1, "opts": ["齐桓公", "晋文公", "楚庄王", "秦穆公"], "q": "春秋时期第一个称霸的诸侯是（ ）", "why": "齐桓公任用管仲改革，首霸中原（葵丘会盟）。"}], "case": {"a": "体现了法家思想指导变法、以制度改革（尤其军功爵与奖励耕织）实现富国强兵；其「废世卿世禄」直接冲击奴隶制贵族特权。", "hints": ["先圈人物与措施：商鞅、军功、耕织、废世卿世禄。", "再想每条措施打的是什么旧制度、立的是什么新秩序。"], "q": "材料（据教材整理）：商鞅在秦国推行变法——按军功授予爵位，废除无军功贵族的特权；奖励耕织，生产多者可免除徭役；废井田、开阡陌，承认土地私有。概括这场变法的指导思想与核心目标。", "steps": ["废世卿世禄、按军功授爵，体现法家「不别亲疏、一断于法」的法治主张。", "奖励耕织+承认土地私有，目标指向发展生产、增强国力（富国）。", "军功爵制打破贵族垄断、调动士兵积极性，指向强兵。", "合起来：以法家思想为指导，通过富国强兵实现秦国的崛起。"], "talk": ["变法类材料题固定拆法：措施→指导思想→目标→影响，四层递进，别只停在复述措施。"], "title": "案例：从措施读变法"}, "intro": "西周的秩序在春秋战国垮掉了：天子式微、诸侯争霸，底层是生产力在变。==铁器和牛耕的推广推动社会大变革，各国变法成为时代潮流，商鞅变法最彻底。==这一节记住一条因果链：生产力变化→土地制度变化→变法→新兴地主阶级崛起。", "learn": [{"h": "纷争的背景：生产力先动", "p": "春秋时期**铁器**开始使用，战国时期**牛耕**推广，生产力显著提高，推动井田制瓦解、**封建土地私有制**逐步确立。经济基础一变，周天子的权威随之衰落（礼崩乐坏），诸侯争霸（齐桓公首霸）与兼并战争接连不断。"}, {"h": "变法运动与商鞅变法", "p": "各国变法的共性：打击奴隶主贵族、扶持新兴地主阶级。秦国的**商鞅变法**（公元前 356 年起，两次）内容最全：政治上废除世卿世禄、推行**县制**、建立什伍连坐；经济上**废井田开阡陌**、奖励耕织、统一度量衡；军事上实行**军功爵制**。\n\n==商鞅变法的历史作用：秦国富强起来，为统一六国奠基，也标志着封建制度在秦国确立。=="}, {"h": "华夏认同", "p": "争霸与兼并客观上促进了区域联系与民族交融，「华夏」认同感在这一时期逐渐形成——这是大一统的思想与社会基础之一。\n\n易错提醒：变法的根本原因是生产力发展（铁器牛耕），不是某个君主「想通了」；答背景题先写这一条。"}], "pitfalls": ["商鞅变法的时间、国家、人物对应错位（秦孝公时期的秦国）。", "把变法原因只答成「为了富国强兵」（那是目标；根本原因是生产力发展与社会转型）。"], "svg": "<text x='185' y='20' text-anchor='middle' font-size='13'>商鞅变法三条线</text><rect x='10' y='35' width='113' height='52' rx='6' fill='#e0f2fe'/><text x='66' y='57' text-anchor='middle' font-size='12'>政治</text><text x='66' y='76' text-anchor='middle' font-size='11'>县制 · 什伍连坐</text><rect x='133' y='35' width='113' height='52' rx='6' fill='#e0f2fe'/><text x='189' y='57' text-anchor='middle' font-size='12'>经济</text><text x='189' y='76' text-anchor='middle' font-size='11'>废井田 · 奖耕织</text><rect x='256' y='35' width='113' height='52' rx='6' fill='#e0f2fe'/><text x='312' y='57' text-anchor='middle' font-size='12'>军事</text><text x='312' y='76' text-anchor='middle' font-size='11'>军功爵制</text><text x='185' y='112' text-anchor='middle' font-size='12' fill='#dc2626'>作用：富国强兵 · 封建制度确立</text>", "svgCap": "商鞅变法：政治、经济、军事三线并进。"}, "video": {"bvid": "BV1Dp4y1375Q", "p": 1, "t": "第2课：诸侯纷争与变法运动（源史社会）", "dur": "55:07", "from": 0, "vtop": ["变法的根本原因是生产力发展（铁器牛耕），不是君主个人想法。", "商鞅变法三线：县制、废井田奖耕织、军功爵制。", "百家争鸣四家关键词：仁、无为、兼爱、法治。"], "vsum": "第2课的逻辑链：铁器牛耕→生产力提高→**井田制**瓦解、土地私有确立→周王室衰微、诸侯纷争→各国变法。**商鞅变法**是样本：政治（县制、什伍连坐、废世卿世禄）、经济（废井田开阡陌、奖励耕织、统一度量衡）、军事（**军功爵制**），==使秦富强并确立封建制度==。思想领域同步爆发**百家争鸣**：儒（仁、仁政、民贵君轻、隆礼重法）、道（无为）、墨（兼爱非攻）、法（以法治国）四家对照记忆。视频为源史社会纲要上第2课精讲（约55:07）。\n易错提醒：变法的根本原因是生产力发展与社会转型，「为了富国强兵」只是目标，不能当作原因来答。", "vtech": ["看到变法背景题 → 第一笔先写生产力（铁器牛耕）与土地制度变革，再写政治需求。", "看到学派辨认题 → 先抓关键词定派（仁/无为/兼爱/法），再比较同派内部差异。", "看到措施类材料 → 按措施→思想→目标→影响四层拆解。"], "vgaokao": []}}, "hist_h004": {"name": "百家争鸣", "sec": 4, "secTitle": "诸侯纷争与变法运动", "page": null, "desc": "儒道墨法四家对照记：仁、无为、兼爱、法治——同一道治国题的四种答案。", "criteria": ["能复述本节核心史实与时间", "能看懂案例史料的解读过程", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清史料依据"], "diag": null, "pre": ["hist_h003"], "next": [], "content": {"advance": {"a": "韩非的主张。依据：强调以严刑峻法加强中央集权、「以法为教」排斥私学——法家集大成者的典型主张。", "kind": "self", "q": "判断学派：「事在四方，要在中央；圣人执要，四方来效。」「以法为教，以吏为师。」这是哪家的主张？依据是什么？"}, "apply": [{"ans": 1, "opts": ["无为而治", "仁政", "兼爱非攻", "以法治国"], "q": "韩非子的核心主张是（ ）", "why": "韩非是法家集大成者，主张以法治国、加强中央集权。"}, {"ans": 2, "opts": ["孔子", "孟子", "荀子", "墨子"], "q": "提出「民为贵，社稷次之，君为轻」的是（ ）", "why": "孟子发展儒家仁政思想，提出民贵君轻。"}], "basics": [{"ans": 0, "opts": ["仁", "无为", "兼爱", "法治"], "q": "孔子思想的核心是（ ）", "why": "孔子以「仁」为核心，主张为政以德、克己复礼。"}, {"ans": 1, "opts": ["法家", "道家", "墨家", "儒家"], "q": "主张「无为而治」、顺应自然的是（ ）", "why": "老子创立道家，主张无为而治、小国寡民。"}], "case": {"a": "都是儒家（孔子、孟子），共同核心是「仁」与德治；差异在孟子把仁发展为系统的仁政学说并提出民贵君轻，对君主的制约更鲜明。", "hints": ["先定学派：两段话都讲德、仁、爱民。", "再找差异：第二段把「民」放到「君」前面，制约君权的意味更强。"], "q": "材料一（大意）：为政以德，譬如北辰，居其所而众星共之。材料二（大意）：民为贵，社稷次之，君为轻。两则材料出自哪一学派？核心主张有何异同？", "steps": ["两则都强调以德治国、重视民众，同属儒家。", "材料一是孔子的「为政以德」：统治者修德，百姓自然归附。", "材料二是孟子的「仁政」与民贵君轻：把人民地位明确置于君主之上。", "异：孟子在孔子基础上把仁政系统化，民本色彩、批判锋芒更突出。"], "talk": ["学派辨认靠关键词：仁/德→儒，道/无为→道家，兼爱→墨，法/术/势→法家。先抓词定派，再谈差异。"], "title": "案例：两段话认学派"}, "intro": "社会大变革，思想大解放。==百家争鸣是战国社会变革在思想领域的反映，各家都在回答同一个问题：天下该怎么治？==背这一节的诀窍是对比记：每家一个关键词、一句代表主张。", "learn": [{"h": "儒家：孔子、孟子、荀子", "p": "**孔子**：核心是「**仁**」，政治上主张**为政以德、克己复礼**，教育上「有教无类」。**孟子**：主张**仁政**，提出**民贵君轻**。**荀子**：主张隆礼重法、性恶论，强调后天教化。三人同属儒家，但孟子重民、荀子重礼法，侧重点不同。"}, {"h": "道家、墨家、法家", "p": "**老子（道家）**：主张**无为而治**、顺应自然，思想含辩证法因素。**墨子（墨家）**：主张**兼爱、非攻、尚贤、节用**，代表平民利益。**韩非（法家）**：集大成，主张**以法治国**、君主专制中央集权，其思想为秦统一提供了理论基础。\n\n==四家治国药方对照：儒家靠德，道家靠无为，墨家靠兼爱，法家靠法治。=="}, {"h": "为什么会百家争鸣", "p": "根源在社会大变革：经济发展、阶级关系变化、私学兴起（士阶层活跃）、各国招贤求治国方案。答「背景」题按这四条组织，答「影响」题写：促进了思想解放、奠定了中国传统文化的基础。"}], "pitfalls": ["孟子（民贵君轻）与荀子（隆礼重法）的主张张冠李戴。", "韩非是法家集大成者，不要写成「提出者」（法家思想先秦多家积累）。"], "svg": "<rect x='10' y='30' width='82' height='44' rx='6' fill='#e0f2fe'/><text x='51' y='49' text-anchor='middle' font-size='12'>儒家</text><text x='51' y='66' text-anchor='middle' font-size='11'>仁 · 德治</text><rect x='102' y='30' width='82' height='44' rx='6' fill='#e0f2fe'/><text x='143' y='49' text-anchor='middle' font-size='12'>道家</text><text x='143' y='66' text-anchor='middle' font-size='11'>无为而治</text><rect x='194' y='30' width='82' height='44' rx='6' fill='#e0f2fe'/><text x='235' y='49' text-anchor='middle' font-size='12'>墨家</text><text x='235' y='66' text-anchor='middle' font-size='11'>兼爱非攻</text><rect x='286' y='30' width='82' height='44' rx='6' fill='#fee2e2'/><text x='327' y='49' text-anchor='middle' font-size='12'>法家</text><text x='327' y='66' text-anchor='middle' font-size='11'>以法治国</text><text x='189' y='100' text-anchor='middle' font-size='12' fill='#64748b'>同一道题（天下怎么治），四种药方</text>", "svgCap": "百家对照：每家一个关键词。"}, "video": {"bvid": "BV1Dp4y1375Q", "p": 1, "t": "第2课：诸侯纷争与变法运动（源史社会）", "dur": "55:07", "from": 0, "vtop": ["变法的根本原因是生产力发展（铁器牛耕），不是君主个人想法。", "商鞅变法三线：县制、废井田奖耕织、军功爵制。", "百家争鸣四家关键词：仁、无为、兼爱、法治。"], "vsum": "第2课的逻辑链：铁器牛耕→生产力提高→**井田制**瓦解、土地私有确立→周王室衰微、诸侯纷争→各国变法。**商鞅变法**是样本：政治（县制、什伍连坐、废世卿世禄）、经济（废井田开阡陌、奖励耕织、统一度量衡）、军事（**军功爵制**），==使秦富强并确立封建制度==。思想领域同步爆发**百家争鸣**：儒（仁、仁政、民贵君轻、隆礼重法）、道（无为）、墨（兼爱非攻）、法（以法治国）四家对照记忆。视频为源史社会纲要上第2课精讲（约55:07）。\n易错提醒：变法的根本原因是生产力发展与社会转型，「为了富国强兵」只是目标，不能当作原因来答。", "vtech": ["看到变法背景题 → 第一笔先写生产力（铁器牛耕）与土地制度变革，再写政治需求。", "看到学派辨认题 → 先抓关键词定派（仁/无为/兼爱/法），再比较同派内部差异。", "看到措施类材料 → 按措施→思想→目标→影响四层拆解。"], "vgaokao": []}}, "hist_h005": {"name": "秦的统一与中央集权制度", "sec": 5, "secTitle": "秦统一多民族封建国家的建立", "page": null, "desc": "前221年统一；皇帝制+三公九卿+郡县制的制度蓝本与多民族国家的疆域。", "criteria": ["能复述本节核心史实与时间", "能看懂案例史料的解读过程", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清史料依据"], "diag": null, "pre": ["hist_h003"], "next": ["hist_h006"], "content": {"advance": {"a": "否。郡县长官由皇帝直接任免、无世袭、不能世袭封地，与分封制下诸侯世袭且有独立性根本不同，说明中央对地方的直接控制——这正是中央集权的关键一步。", "kind": "self", "q": "有人说郡县制是「换了名字的分封制」。你是否同意？用制度细节说明理由。"}, "apply": [{"ans": 1, "opts": ["分封制", "郡县制", "内外服制", "宗法制"], "q": "秦朝在地方上推行、并影响此后两千多年的制度是（ ）", "why": "郡县制：地方长官由皇帝任免，中央集权在地方的落地。"}, {"ans": 2, "opts": ["丞相", "太尉", "御史大夫", "郡守"], "q": "三公中负责监察百官的是（ ）", "why": "御史大夫负责监察百官、掌管律令图籍。"}], "basics": [{"ans": 0, "opts": ["皇帝制度", "三公九卿制", "郡县制", "科举制"], "q": "秦朝中央集权制度中，权力高度集中的源头是（ ）", "why": "皇帝制度确立了皇帝至高无上的地位，是整套制度的顶端。"}, {"ans": 1, "opts": ["公元前230年", "公元前221年", "公元前209年", "公元前207年"], "q": "秦完成统一是在（ ）", "why": "前230—前221年，秦先后灭韩、赵、魏、楚、燕、齐六国，前221年完成统一。"}], "case": {"a": "弊在分封：诸侯世袭且独立性强，易形成割据、威胁中央；利在郡县：长官由皇帝任免、不得世袭，中央可直接控制地方。结论：郡县制取代分封制是中央集权强化的必然。", "hints": ["对比维度：任命方式、是否世袭、与中央的关系。", "柳宗元是唐朝人，他的评论是后世对这场争论的总结性评价，属于历史解释类材料。"], "q": "材料（大意，据《封建论》整理）：秦用郡县而天下安，汉初分封诸侯王而七国乱作。结合所学，分析郡县制比分封制「安」在哪里。", "steps": ["分封制下诸侯世袭、有军有政，封国尾大不掉，汉初七国之乱就是实证。", "郡县制下郡守、县令由皇帝直接任免调动，无世袭、无封地，权力收回中央。", "评价制度要看维稳效果：郡县制切断了地方割据的制度根源。"], "talk": ["制度对比题用三格表：任命/世袭/与中央关系，逐项对开写，比散文式作答更得分。"], "title": "案例：郡县为什么比分封「安」"}, "intro": "公元前 221 年，秦完成统一，建立起中国历史上第一个统一的多民族封建国家。==秦的核心创造是中央集权制度：皇帝制（顶层）+三公九卿（中央）+郡县制（地方），构成此后两千年王朝制度的蓝本。==", "learn": [{"h": "统一的过程与条件", "p": "公元前 230—前 221 年，秦用远交近攻等策略先后灭**韩、赵、魏、楚、燕、齐**（顺序要记准）。能统一的条件：人民渴望安定、各区域经济联系加强（客观）；商鞅变法后秦国力最强、历代秦王励精图治（主观）。"}, {"h": "中央集权制度三件套", "p": "**皇帝制度**：皇帝称号、皇权至上、皇位世袭，国家大事由皇帝裁决。**三公九卿制**：丞相（行政）、太尉（军事）、御史大夫（监察）组成中央政府，分掌政务。**郡县制**：全国分郡、县两级，长官由皇帝直接任免。\n\n==判断一种地方制度看三点：谁任命、能否世袭、听谁的。郡县三点全归中央，这就是它与分封的本质区别。=="}, {"h": "疆域与多民族国家", "p": "秦疆域：东至海暨朝鲜，西至临洮、羌中，南至北向户，北据河为塞、并阴山至辽东。北击匈奴、修长城，南征百越设桂林、南海、象三郡——把多个民族地区纳入统一治理，「多民族」三字是本课标题的关键词。"}], "pitfalls": ["灭六国顺序记错（韩赵魏楚燕齐）。", "三公分工混淆（尤其御史大夫是监察不是行政）。", "把郡县制说成秦始皇凭空发明（战国已有县、郡雏形，秦是全面推行并制度化）。"], "svg": "<rect x='135' y='10' width='110' height='30' rx='6' fill='#2563eb'/><text x='190' y='30' text-anchor='middle' font-size='13' fill='#fff'>皇帝</text><rect x='15' y='68' width='105' height='30' rx='6' fill='#e0f2fe'/><text x='67' y='88' text-anchor='middle' font-size='12'>丞相（行政）</text><rect x='140' y='68' width='105' height='30' rx='6' fill='#e0f2fe'/><text x='192' y='88' text-anchor='middle' font-size='12'>太尉（军事）</text><rect x='265' y='68' width='105' height='30' rx='6' fill='#e0f2fe'/><text x='317' y='88' text-anchor='middle' font-size='12'>御史大夫（监察）</text><rect x='80' y='122' width='100' height='28' rx='6' fill='#dbeafe'/><text x='130' y='141' text-anchor='middle' font-size='12'>郡（守）</text><rect x='210' y='122' width='100' height='28' rx='6' fill='#dbeafe'/><text x='260' y='141' text-anchor='middle' font-size='12'>县（令/长）</text>", "svgCap": "秦的中央集权框架：皇帝—三公九卿—郡县。"}, "video": {"bvid": "BV1F94y1k7k4", "p": 1, "t": "第3课：秦统一多民族封建国家的建立（源史社会）", "dur": "49:42", "from": 0, "vtop": ["前221年秦统一，灭六国顺序：韩赵魏楚燕齐。", "中央集权三件套：皇帝制、三公九卿、郡县制。", "巩固四件套（文、币、衡、轨）是正面，焚书坑儒与暴政是反面。"], "vsum": "第3课分两半：统一与制度——前230至前221年灭六国（韩赵魏楚燕齐），==建立第一个统一的多民族封建国家==；**皇帝制**、**三公九卿制**（丞相行政、太尉军事、御史大夫监察）、**郡县制**构成中央集权蓝本，北击匈奴、南征百越拓展疆域。巩固与速亡——书同文（小篆）、币同制（半两钱）、衡同量、车同轨功在长远；焚书坑儒、严刑峻法、繁重徭役激化矛盾，前209年**大泽乡起义**、前207年秦亡。评价秦始皇必须两面看。视频为源史社会纲要上第3课精讲（49:42）。\n易错提醒：三公分工最容易记混，丞相管行政、太尉管军事、御史大夫管监察，御史大夫不是行政官。", "vtech": ["看到制度对比 → 用三格表：谁任命、能否世袭、与中央关系。", "看到原因分析 → 分层：导火索→统治政策→根本矛盾，最后一句史家评价收尾。", "看到评价人物 → 功过两面各列实据，禁止一边倒。"], "vgaokao": []}}, "hist_h006": {"name": "巩固统一的措施与秦的速亡", "sec": 6, "secTitle": "秦统一多民族封建国家的建立", "page": null, "desc": "书同文、车同轨、币同制、衡同量对照暴政：大泽乡起义与前207年秦亡。", "criteria": ["能复述本节核心史实与时间", "能看懂案例史料的解读过程", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清史料依据"], "diag": null, "pre": ["hist_h005"], "next": ["hist_h007"], "content": {"advance": {"a": "「攻守之势异也」指秦从夺取天下转为守天下，形势变了；「仁义不施」指统一后没有改行仁政、依旧暴政。贾谊的结论：政策必须随形势转变，及时休养生息才是长治之道。", "kind": "self", "q": "贾谊《过秦论》说秦亡的原因是「仁义不施而攻守之势异也」。逐句解释这句话，并说出它给后世统治者的启示。"}, "apply": [{"ans": 1, "opts": ["焚书坑儒", "大泽乡起义", "巨鹿之战", "鸿门宴"], "q": "中国历史上第一次大规模农民起义是（ ）", "why": "前209年陈胜、吴广领导的大泽乡起义，揭开秦末农民战争序幕。"}, {"ans": 2, "opts": ["统一货币", "统一文字", "焚书坑儒", "修筑长城"], "q": "下列措施中属于思想文化控制、且评价以负面为主的是（ ）", "why": "焚书坑儒钳制思想、摧残文化，是秦暴政在文化领域的体现。"}], "basics": [{"ans": 0, "opts": ["统一文字（小篆）", "统一车轨", "统一货币", "统一度量衡"], "q": "秦统一后颁行全国的标准字体是依托哪项措施实现的（ ）", "why": "以秦国小篆为标准字体，统一文字（后又推行隶书）。"}, {"ans": 1, "opts": ["圆形方孔半两钱", "刀币", "布币", "蚁鼻钱"], "q": "秦统一的货币是（ ）", "why": "废除六国货币，统一为圆形方孔半两钱。"}], "case": {"a": "根本原因是秦的暴政（徭役繁重、赋税沉重、刑罚严酷）激化社会矛盾；遇雨失期只是导火索。贾谊「仁义不施」的论断与此一致。", "hints": ["先找起义口号：「王侯将相宁有种乎」反映的是反抗等级压迫。", "再对照秦政：徭役（阿房宫、骊山陵）、严刑峻法、重税。", "区分导火索与根本原因。"], "q": "材料（大意，据教材整理）：陈胜、吴广等 900 名戍卒遇雨误期，按秦律当斩，于是揭竿而起，喊出「王侯将相宁有种乎」。分析秦速亡的根本原因。", "steps": ["表面原因：戍边误期、律法严苛（失期当斩），逼得戍卒铤而走险。", "深层数据：秦大规模征用民力修宫陵、长城、驰道，徭役兵役沉重；赋税重、刑法残酷。", "得出结论：暴政使社会矛盾全面激化，起义是必然——导火索是雨，火药是暴政。"], "talk": ["原因题分层答：直接原因/导火索→根本原因（统治政策）→用一句史家评价收尾，层次就是分数。"], "title": "案例：大泽乡起义的原因分层"}, "intro": "制度创新的另一面是巩固与失控。==巩固统一的措施（书同文、车同轨、币同制、衡同量）影响深远；但暴政让这个强大的王朝 15 年就崩塌了。==这一节一正一反：措施记全，亡因会析。", "learn": [{"h": "巩固统一的四件套", "p": "**统一文字**（小篆为标准，后推隶书）、**统一货币**（圆形方孔半两钱）、**统一度量衡**、**车同轨**并修驰道直道；政治上编制户籍、迁徙六国豪强到关中；边疆上北修长城、南设三郡。这些措施加强了经济文化交流与中央控制，意义以正面评价为主。"}, {"h": "思想控制与暴政", "p": "为统一思想，秦始皇下令**焚书坑儒**，钳制思想、摧残文化。统治上：法律严苛、徭役繁重（修阿房宫、骊山陵、长城、驰道）、赋税沉重。\n\n==评价秦始皇要两面看：统一与制度建设是千古功业，暴政速亡是深刻教训——考试最忌只说一面。=="}, {"h": "秦的灭亡", "p": "公元前 209 年**大泽乡起义**爆发（陈胜、吴广，「王侯将相宁有种乎」），前 207 年刘邦入关中，秦亡；随后楚汉之争，刘邦胜出。此段只需记两个点位：前 209 起义、前 207 秦亡。"}], "pitfalls": ["巩固措施只记政治、漏掉经济文化（货币、度量衡、文字、车轨）。", "秦亡年份记错（前207，不是前221/前206）。", "评价一边倒：只夸统一或只骂暴政。"], "svg": "<rect x='15' y='30' width='82' height='44' rx='6' fill='#dcfce7'/><text x='56' y='49' text-anchor='middle' font-size='12'>书同文</text><text x='56' y='66' text-anchor='middle' font-size='11'>小篆标准</text><rect x='107' y='30' width='82' height='44' rx='6' fill='#dcfce7'/><text x='148' y='49' text-anchor='middle' font-size='12'>币同制</text><text x='148' y='66' text-anchor='middle' font-size='11'>半两钱</text><rect x='199' y='30' width='82' height='44' rx='6' fill='#dcfce7'/><text x='240' y='49' text-anchor='middle' font-size='12'>衡同量</text><text x='240' y='66' text-anchor='middle' font-size='11'>度量衡统一</text><rect x='291' y='30' width='82' height='44' rx='6' fill='#dcfce7'/><text x='332' y='49' text-anchor='middle' font-size='12'>车同轨</text><text x='332' y='66' text-anchor='middle' font-size='11'>修驰道直道</text><text x='194' y='100' text-anchor='middle' font-size='12' fill='#dc2626'>对照面：焚书坑儒 · 严刑峻法 · 繁重徭役 → 前209 大泽乡起义</text>", "svgCap": "巩固措施四件套（正面）与暴政（速亡之因）要成对记忆。"}, "video": {"bvid": "BV1F94y1k7k4", "p": 1, "t": "第3课：秦统一多民族封建国家的建立（源史社会）", "dur": "49:42", "from": 0, "vtop": ["前221年秦统一，灭六国顺序：韩赵魏楚燕齐。", "中央集权三件套：皇帝制、三公九卿、郡县制。", "巩固四件套（文、币、衡、轨）是正面，焚书坑儒与暴政是反面。"], "vsum": "第3课分两半：统一与制度——前230至前221年灭六国（韩赵魏楚燕齐），==建立第一个统一的多民族封建国家==；**皇帝制**、**三公九卿制**（丞相行政、太尉军事、御史大夫监察）、**郡县制**构成中央集权蓝本，北击匈奴、南征百越拓展疆域。巩固与速亡——书同文（小篆）、币同制（半两钱）、衡同量、车同轨功在长远；焚书坑儒、严刑峻法、繁重徭役激化矛盾，前209年**大泽乡起义**、前207年秦亡。评价秦始皇必须两面看。视频为源史社会纲要上第3课精讲（49:42）。\n易错提醒：三公分工最容易记混，丞相管行政、太尉管军事、御史大夫管监察，御史大夫不是行政官。", "vtech": ["看到制度对比 → 用三格表：谁任命、能否世袭、与中央关系。", "看到原因分析 → 分层：导火索→统治政策→根本矛盾，最后一句史家评价收尾。", "看到评价人物 → 功过两面各列实据，禁止一边倒。"], "vgaokao": []}}, "hist_h007": {"name": "西汉的巩固与汉武帝的大一统", "sec": 7, "secTitle": "西汉与东汉——统一多民族封建国家的巩固", "page": null, "desc": "文景之治打底，武帝四线推进：推恩令、盐铁官营、独尊儒术、北击匈奴通西域。", "criteria": ["能复述本节核心史实与时间", "能看懂案例史料的解读过程", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清史料依据"], "diag": null, "pre": ["hist_h006"], "next": ["hist_h008"], "content": {"advance": {"a": "错。察举制由地方长官考察推荐、朝廷任命，本质是自上而下的选拔；科举是隋唐以后士人自愿报名、考试定去取的制度，出现时间与运行方式都不同。", "kind": "self", "q": "有人说察举制就是早期的科举制。对吗？说明两者的关键区别。"}, "apply": [{"ans": 1, "opts": ["分封制", "推恩令", "郡县制", "盐铁官营"], "q": "汉武帝为削弱诸侯王势力颁布的是（ ）", "why": "推恩令令诸侯子弟分封土地，王国越分越小。"}, {"ans": 2, "opts": ["文帝", "景帝", "武帝", "光武帝"], "q": "「罢黜百家，独尊儒术」发生在（ ）", "why": "汉武帝接受董仲舒建议，确立儒家思想的正统地位。"}], "basics": [{"ans": 0, "opts": ["与民休息、轻徭薄赋", "大规模对外战争", "罢黜百家", "盐铁官营"], "q": "文景之治出现的主要原因是西汉初年统治者（ ）", "why": "汉初吸取秦亡教训，休养生息，出现文景之治。"}, {"ans": 1, "opts": ["郡国并行制", "郡县制", "分封制", "行省制"], "q": "西汉初期地方行政实行的是（ ）", "why": "汉初郡县与封国并存，称郡国并行制，后引发诸侯王问题。"}], "case": {"a": "材料讲的是推恩令：用「分封子弟」的温和方式分割王国，避免正面冲突（不削而削）。影响：诸侯王势力大减，中央集权加强，为大一统扫清政治障碍。", "hints": ["关键词是「分」和「众建」：让诸侯自己把地分小。", "对比一下汉景帝时期的「削藩」引发了什么（七国之乱），就懂武帝这招的高明。"], "q": "材料（大意，据教材整理）：汉武帝允许诸侯王把封地分给子弟，子弟皆可封侯，王国土地越分越小、势力渐弱。这项政策的名称、特点和影响是什么？", "steps": ["名称：推恩令（主父偃建议）。", "特点：表面是皇恩分封，实质是分割王国，且以制度形式推行、阻力小。", "影响：王国问题基本解决（再配合酌金夺爵剥夺爵位），中央对地方的控制大大加强。"], "talk": ["政策题固定三问：叫什么、怎么做、效果如何。先从材料里找动作词（分、建、夺），政策名称自然浮现。"], "title": "案例：一道「分地」令读出推恩令"}, "intro": "西汉从郡国并行走到大一统，靠的是一套组合拳。==汉武帝的大一统是政治、经济、思想、军事四线同时推进，目标都是同一个：加强中央集权。==这一节按四线记，比按时间背流水账高效得多。", "learn": [{"h": "从郡国并行到中央集权（政治线）", "p": "汉初实行**郡国并行制**，诸侯王势力膨胀（景帝时爆发七国之乱）。武帝用**推恩令**分割王国，又以**酌金夺爵**剥夺部分王侯爵位；中央设中朝削弱相权，地方设**刺史**监察郡国；选官推行**察举制**（以孝廉等科目举荐人才）。\n\n==推恩令的精髓是「分而弱之」，不用兵就解决了王国问题。=="}, {"h": "经济线与思想线", "p": "经济：**盐铁官营**、统一铸造**五铢钱**、均输平准、抑制富商大贾。思想：接受董仲舒建议，**罢黜百家、独尊儒术**，在长安设**太学**，儒家思想成为正统、儒学教育官方化。\n\n军事线：派**卫青、霍去病**北击匈奴，派**张骞**两次出使西域，丝绸之路开通——大一统的疆域与交流维度。"}, {"h": "先修一笔：文景之治", "p": "武帝之前的底子是高祖至景帝的休养生息：轻徭薄赋（三十税一）、重视农业、文帝废除肉刑。**文景之治**积累了国力，才撑得起武帝的大动作。答「武帝措施的前提/背景」时要带上它。"}], "pitfalls": ["推恩令（武帝）与七国之乱（景帝时）的时间线错位。", "刺史是监察官，不是地方行政长官。", "察举制≠科举制（科举隋唐才有）。"], "svg": "<text x='190' y='20' text-anchor='middle' font-size='13'>汉武帝大一统四线</text><rect x='10' y='35' width='85' height='40' rx='6' fill='#e0f2fe'/><text x='52' y='52' text-anchor='middle' font-size='12'>政治</text><text x='52' y='68' text-anchor='middle' font-size='11'>推恩令·刺史</text><rect x='105' y='35' width='85' height='40' rx='6' fill='#e0f2fe'/><text x='147' y='52' text-anchor='middle' font-size='12'>经济</text><text x='147' y='68' text-anchor='middle' font-size='11'>盐铁官营·五铢钱</text><rect x='200' y='35' width='85' height='40' rx='6' fill='#e0f2fe'/><text x='242' y='52' text-anchor='middle' font-size='12'>思想</text><text x='242' y='68' text-anchor='middle' font-size='11'>独尊儒术·太学</text><rect x='295' y='35' width='85' height='40' rx='6' fill='#e0f2fe'/><text x='337' y='52' text-anchor='middle' font-size='12'>军事</text><text x='337' y='68' text-anchor='middle' font-size='11'>北击匈奴·通西域</text>", "svgCap": "大一统四条线，每条线记两个抓手措施。"}, "video": {"bvid": "BV1gu41177pa", "p": 1, "t": "第4课：西汉与东汉——统一多民族封建国家的巩固（源史社会）", "dur": "2:28:14", "from": 0, "vtop": ["大一统四线：政治推恩令、经济盐铁官营、思想独尊儒术、军事击匈奴通西域。", "东汉衰亡是条链：兼并→豪强→专权→黄巾起义。", "察举制不是科举制，刺史是监察不是行政长官。"], "vsum": "第4课是「巩固」的正反两面：西汉先有郡国并行与七国之乱的教训，再有文景之治的积累，==最终汉武帝四线推进大一统==（**推恩令**与刺史、盐铁官营与五铢钱、**独尊儒术**与太学、卫霍北击与张骞通西域）。东汉刘秀光武中兴（定都洛阳、柔道治国），但中后期土地兼并使豪强坐大、外戚宦官交替专权，184年**黄巾起义**后中央集权瓦解、军阀割据。视频为源史社会纲要上第4课精讲（2:28:14）。\n易错提醒：刺史是监察官，不是地方行政长官，别把刺史当成一级地方行政机构的长官。", "vtech": ["看到政策类材料 → 先找动作词（分、夺、监察）定政策名，再答特点与影响。", "看到衰亡类问题 → 先画因果链再动笔：兼并→豪强→专权→起义→割据。", "看到选官制度 → 先分时代：察举是汉代推荐制，科举是隋唐考试制，别跨代。"], "vgaokao": []}}, "hist_h008": {"name": "东汉的兴衰", "sec": 8, "secTitle": "西汉与东汉——统一多民族封建国家的巩固", "page": null, "desc": "光武中兴与衰亡因果链：土地兼并→豪强坐大→外戚宦官专权→黄巾起义。", "criteria": ["能复述本节核心史实与时间", "能看懂案例史料的解读过程", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清史料依据"], "diag": null, "pre": ["hist_h007"], "next": [], "content": {"advance": {"a": "光武帝：建国初期，百废待兴，需要收拾人心、恢复生产，故以柔治国、整顿吏治、恢复经济。东汉中后期：皇帝年幼、外戚宦官轮流专权，政治腐败，豪强兼并激化矛盾，统治走向腐朽而非巩固。", "kind": "self", "q": "东汉与西汉同为汉家天下，为什么光武帝时是「中兴」、中后期却走向衰亡？从统治集团与政策两个角度各说一点。"}, "apply": [{"ans": 1, "opts": ["农民起义直接推翻", "外戚宦官专权与豪强割据使中央失控", "匈奴入侵灭亡东汉", "宦官集团发动政变改朝换代"], "q": "东汉后期政局动荡的根本表现是（ ）", "why": "外戚宦官交替专权、豪强地主势力膨胀，中央控制力瓦解，最终军阀割据。"}, {"ans": 2, "opts": ["大泽乡起义", "赤眉起义", "黄巾起义", "黄巢起义"], "q": "184 年爆发的起义是（ ）", "why": "张角领导的黄巾起义沉重打击东汉统治。"}], "basics": [{"ans": 0, "opts": ["光武帝刘秀", "汉武帝刘彻", "汉高祖刘邦", "汉明帝刘庄"], "q": "东汉的建立者是（ ）", "why": "公元 25 年刘秀称帝，定都洛阳，史称光武帝。"}, {"ans": 1, "opts": ["长安", "洛阳", "咸阳", "开封"], "q": "东汉的都城是（ ）", "why": "刘秀定都洛阳，故称东汉（以长安为西汉相对）。"}], "case": {"a": "反映东汉土地兼并严重、豪强地主势力膨胀，农民失去土地是社会矛盾激化的经济根源；豪强既是地方势力的根基，也是东汉中央集权衰弱的根源。", "hints": ["抓住对比：占有比例与人口比例严重失衡。", "再往下想：豪强庄园经济独立性强，中央征税征兵都受影响。"], "q": "材料（据教材整理）：东汉时期，豪强地主「田亩连于方国」，庄园里聚集大量依附人口，国家能直接控制的编户齐民不断减少。材料反映了什么问题？与东汉衰亡有何关系？", "steps": ["信息提取：土地高度集中于豪强，依附人口脱离国家户籍控制。", "问题定性：土地兼并严重，豪强地主势力膨胀。", "关系分析：豪强坐大→中央财税与兵源受损→地方割据有土壤；农民失地→矛盾激化→黄巾起义。"], "talk": ["经济类材料题：先算「谁占有了什么」，再推「对国家控制力的影响」，最后接政治后果。"], "title": "案例：从土地兼并看东汉衰亡"}, "intro": "东汉的故事是「中兴开局、腐败收尾」。==光武中兴靠的是柔道治国与整顿吏治；衰亡的根子是豪强地主坐大与外戚宦官专权，最后被黄巾起义掀翻。==这一课重点不在记人名，在看懂衰亡的因果链。", "learn": [{"h": "光武中兴", "p": "公元 **25 年**刘秀（光武帝）定都**洛阳**建东汉。他吸取西汉末年教训：释放奴婢、减轻徭役赋税、整顿吏治、合并郡县、裁减官吏，加强对官僚与外戚的控制，社会经济得到恢复，史称**光武中兴**。"}, {"h": "衰亡的因果链", "p": "东汉中后期皇帝多幼年即位，形成**外戚与宦官交替专权**的局面，政治腐败；同时**豪强地主**兼并土地、建立庄园，势力膨胀，中央控制力持续流失。\n\n==衰亡链条要背全：兼并土地→豪强坐大→中央失控→矛盾激化→黄巾起义→军阀割据。==184 年**黄巾起义**（张角）后，东汉名存实亡，州牧领兵形成军阀割据。"}, {"h": "与西汉对照记", "p": "西汉强在「集权推进」（推恩令等），东汉衰在「集权流失」（豪强、外戚、宦官三方掏空中央）。考试常出对照题：同一主题（一统的建立与巩固）下，西汉是巩固、东汉前期是再巩固、后期是瓦解。"}], "pitfalls": ["东汉都城写成长安（洛阳！）。", "黄巾起义年份记错（184 年）。", "把外戚宦官专权当作衰亡的唯一原因，漏掉土地兼并这条经济线。"], "svg": "<text x='190' y='18' text-anchor='middle' font-size='12'>东汉衰亡因果链</text><rect x='5' y='32' width='86' height='32' rx='6' fill='#fee2e2'/><text x='48' y='53' text-anchor='middle' font-size='11'>土地兼并</text><rect x='101' y='32' width='86' height='32' rx='6' fill='#fee2e2'/><text x='144' y='53' text-anchor='middle' font-size='11'>豪强坐大</text><rect x='197' y='32' width='86' height='32' rx='6' fill='#fee2e2'/><text x='240' y='53' text-anchor='middle' font-size='11'>外戚宦官专权</text><rect x='293' y='32' width='86' height='32' rx='6' fill='#fca5a5'/><text x='336' y='53' text-anchor='middle' font-size='11'>黄巾起义·割据</text><text x='96' y='53' font-size='12'>→</text><text x='192' y='53' font-size='12'>→</text><text x='288' y='53' font-size='12'>→</text>", "svgCap": "衰亡不是一件事：兼并、豪强、专权、起义四步相连。"}, "video": {"bvid": "BV1gu41177pa", "p": 1, "t": "第4课：西汉与东汉——统一多民族封建国家的巩固（源史社会）", "dur": "2:28:14", "from": 0, "vtop": ["大一统四线：政治推恩令、经济盐铁官营、思想独尊儒术、军事击匈奴通西域。", "东汉衰亡是条链：兼并→豪强→专权→黄巾起义。", "察举制不是科举制，刺史是监察不是行政长官。"], "vsum": "第4课是「巩固」的正反两面：西汉先有郡国并行与七国之乱的教训，再有文景之治的积累，==最终汉武帝四线推进大一统==（**推恩令**与刺史、盐铁官营与五铢钱、**独尊儒术**与太学、卫霍北击与张骞通西域）。东汉刘秀光武中兴（定都洛阳、柔道治国），但中后期土地兼并使豪强坐大、外戚宦官交替专权，184年**黄巾起义**后中央集权瓦解、军阀割据。视频为源史社会纲要上第4课精讲（2:28:14）。\n易错提醒：刺史是监察官，不是地方行政长官，别把刺史当成一级地方行政机构的长官。", "vtech": ["看到政策类材料 → 先找动作词（分、夺、监察）定政策名，再答特点与影响。", "看到衰亡类问题 → 先画因果链再动笔：兼并→豪强→专权→起义→割据。", "看到选官制度 → 先分时代：察举是汉代推荐制，科举是隋唐考试制，别跨代。"], "vgaokao": []}}, "hist_h009": {"name": "三国与西晋：鼎立、统一与民族内迁", "sec": 1, "secTitle": "三国两晋南北朝的政权更迭与民族交融", "page": null, "desc": "220魏、221蜀、229吴鼎立；266西晋建、280统一、316亡；匈奴鲜卑羯氐羌内迁。", "criteria": ["能复述本节核心史实与时间", "能看懂案例史料的解读过程", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清史料依据"], "diag": null, "pre": [], "next": ["hist_h010"], "content": {"advance": {"a": "分裂指政权并立与更迭；交融指北方各族内迁后与汉族杂居，在生产、语言、风俗上互相影响。政权层面是分，社会与民族层面却在走向融合，两条线要分开看。", "kind": "self", "q": "为什么说三国到西晋是「分裂中孕育交融」？"}, "apply": [{"ans": 1, "opts": ["结束了三国鼎立", "为民族交融创造了条件", "直接导致西晋建立", "使江南得到开发"], "q": "北方各族内迁对历史发展的主要影响是（ ）", "why": "内迁各族与汉族杂居、互相学习，为此后民族交融创造条件；江南开发主要与北人南迁相关。"}, {"ans": 1, "opts": ["推行科举制", "八王之乱与统治腐朽", "北魏孝文帝改革", "安史之乱"], "q": "西晋迅速灭亡的重要原因是（ ）", "why": "八王之乱严重消耗西晋国力，加上统治腐朽，西晋很快灭亡。"}], "basics": [{"ans": 2, "opts": ["220年曹丕称帝", "221年刘备称帝", "229年孙权称帝", "280年西晋灭吴"], "q": "三国鼎立正式形成的标志是（ ）", "why": "229年孙权称帝后，魏、蜀、吴三政权并立，鼎立正式形成。"}, {"ans": 1, "opts": ["266年", "280年", "316年", "439年"], "q": "西晋完成统一是在（ ）", "why": "280年西晋灭吴，结束三国鼎立，完成统一。"}], "case": {"a": "赤壁之战奠定了三国鼎立的雏形：曹操无力统一南方，南北对峙长期化。", "hints": ["先定位时间与结果：208年，曹操败、退回北方。", "再联系前后：此前曹操已统一北方，此后三国鼎立雏形出现。"], "q": "材料（大意，据教材整理）：208年曹操率军南下，在赤壁被孙刘联军击败，退回北方，此后无力南下，南方相对稳定。结合所学，说明赤壁之战对政局的影响。", "steps": ["曹操统一北方后南下受挫，南北对峙格局形成。", "孙刘联盟保住南方，为后来蜀汉、吴的建立创造条件。", "所以赤壁之战不是一次普通胜负，而是鼎立格局形成的转折。"], "talk": ["时空观念题先钉年份再谈影响：208年这个点，把官渡（统一北方）和229年鼎立正式形成串起来。"], "title": "案例：从赤壁之战读出鼎立成因"}, "intro": "东汉末年军阀割据，最终走向三国鼎立，又被西晋短暂统一。==这一段的主线是：政权不断更迭，但北方各族内迁的脚步没有停，民族交融在分裂中悄悄推进。==", "learn": [{"h": "三国鼎立的形成", "p": "**220年**曹丕称帝建**魏**，**221年**刘备称帝建**蜀汉**，**229年**孙权称帝建**吴**，三国鼎立正式形成。此前**官渡之战（200年）**奠定曹操统一北方基础，**赤壁之战（208年）**奠定鼎立雏形。\n\n==记鼎立只钉三个年份：220魏、221蜀、229吴。=="}, {"h": "西晋的短暂统一与崩溃", "p": "**266年**司马炎建立**西晋**，**280年**灭吴完成统一。但西晋统治腐朽，又爆发**八王之乱**，国力大损；随后**永嘉之乱**后，**316年**西晋灭亡。\n\n==西晋是短暂统一：统一快，崩溃也快，根子在统治集团内斗与腐朽。=="}, {"h": "北方各族内迁", "p": "东汉以来，**匈奴、鲜卑、羯、氐、羌**等北方和西北各族陆续内迁（教材常称「五胡」内迁）。他们与汉族杂居，学习汉族生产与文化，也带来畜牧等生产经验。\n\n==内迁不是交融的完成，而是交融的起点：杂居、通婚、互相学习才一步步走向融合。=="}], "pitfalls": ["220、221、229 三个建国年份与对应政权对错位。", "把赤壁之战说成鼎立正式形成（它只是奠定雏形，正式形成在229年）。", "把「内迁」和后来的「北人南迁开发江南」混为一谈。"], "svg": "<rect x='10' y='30' width='110' height='36' rx='6' fill='#e0f2fe'/><text x='65' y='53' text-anchor='middle' font-size='12'>魏 220</text><rect x='140' y='30' width='110' height='36' rx='6' fill='#e0f2fe'/><text x='195' y='53' text-anchor='middle' font-size='12'>蜀汉 221</text><rect x='270' y='30' width='110' height='36' rx='6' fill='#e0f2fe'/><text x='325' y='53' text-anchor='middle' font-size='12'>吴 229</text><rect x='130' y='90' width='130' height='34' rx='6' fill='#dbeafe'/><text x='195' y='112' text-anchor='middle' font-size='12'>西晋 280 统一</text>", "svgCap": "三国鼎立到西晋统一的时间轴。"}, "video": {"bvid": "BV1kh4y1T7Sm", "p": 1, "t": "第5课：三国两晋南北朝的政权更迭与民族交融（源史社会）", "dur": "1:08:42", "from": 0, "vtop": ["鼎立三年份：220魏、221蜀、229吴；西晋280统一、316灭亡。", "内迁是交融的起点，孝文帝改革是交融的高潮，江南开发靠北人南迁。", "439年只是北魏统一北方，589年才是隋统一全国，别混。"], "vsum": "第5课分南北两线看：北方从**三国鼎立**（220魏、221蜀、229吴）到西晋短暂统一（280统一、316灭亡），匈奴、鲜卑、羯、氐、羌内迁埋下交融种子；西晋亡后北方**十六国**混战，439年**北魏**统一北方，孝文帝迁都洛阳==推行汉化改革，加速民族交融==；南方东晋与宋、齐、梁、陈相继，北人南迁带来劳动力与技术，江南得到开发。视频为源史社会纲要上第5课精讲（1:08:42）。\n易错提醒：439年只是北魏统一北方，全国统一要到589年隋灭陈，两个年份和事件千万别对错位。", "vtech": ["看到政权更迭题 → 先画时间轴：鼎立（220/221/229）→西晋统一（280）→分裂（316后）→北魏统一北方（439）。", "看到改革措施材料 → 先归类（服饰/语言/姓氏/婚姻）再答共同指向，不要逐条抄材料。", "看到开发类问题 → 按人、技术、环境三因组织：北人南迁、技术传入、南方安定。"], "vgaokao": []}}, "hist_h010": {"name": "东晋南朝与十六国北朝：民族交融之路", "sec": 2, "secTitle": "三国两晋南北朝的政权更迭与民族交融", "page": null, "desc": "东晋与宋齐梁陈；439北魏统一北方；孝文帝改革与江南开发。", "criteria": ["能复述本节核心史实与时间", "能看懂案例史料的解读过程", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清史料依据"], "diag": null, "pre": ["hist_h009"], "next": [], "content": {"advance": {"a": "改革加速鲜卑汉化与交融、增强国力；但迁都与汉化疏远了北方六镇鲜卑军镇，守边集团与洛阳朝廷矛盾加深，后来六镇起义动摇北魏统治。一项改革的正反两面要同时说清。", "kind": "self", "q": "孝文帝改革为什么既是交融的高潮，又埋下北魏分裂的种子？"}, "apply": [{"ans": 1, "opts": ["海外贸易兴起", "北方人口南迁带来劳动力与技术", "科举制推行", "大运河开通"], "q": "江南地区在东晋南朝时期得到开发的最主要原因是（ ）", "why": "北人南迁带来劳动力与先进技术，是江南开发的首要原因；大运河是隋代。"}, {"ans": 1, "opts": ["结束了南北分裂", "促进了民族交融与北魏封建化", "直接统一全国", "创立了三省六部制"], "q": "孝文帝改革的历史作用主要是（ ）", "why": "改革促进民族交融与封建化，但没有直接结束南北分裂；三省六部是隋唐制度。"}], "basics": [{"ans": 1, "opts": ["东晋", "北魏", "前秦", "南朝宋"], "q": "统一北方、结束十六国混战的政权是（ ）", "why": "439年北魏统一北方。"}, {"ans": 2, "opts": ["长安", "平城", "洛阳", "建康"], "q": "北魏孝文帝迁都的地点是（ ）", "why": "494年孝文帝迁都洛阳，便于推行汉化改革。"}], "case": {"a": "共同指向是推行汉化、促进民族交融；它巩固了北魏统治，也为后来隋唐统一与制度融合打下基础。", "hints": ["先抓共同点：服饰、语言、姓氏、婚姻都指向文化与生活方式。", "再想目的：不是单项整顿，而是主动向汉族文化靠拢。"], "q": "材料（大意，据教材整理）：北魏孝文帝迁都洛阳后，下令鲜卑贵族改穿汉服、朝廷上说汉语、改汉姓，并鼓励与汉族通婚。结合所学，概括这些措施的共同指向。", "steps": ["这些措施都属于汉化（封建化）改革内容。", "目的在于缓和民族矛盾、巩固统治，并促进鲜卑与汉族的融合。", "效果要两面看：促进交融与政权稳定，但也引起部分鲜卑贵族不满。"], "talk": ["措施归类题先找共同指向再答影响，不要逐条复述材料。"], "title": "案例：从孝文帝措施读改革方向"}, "intro": "西晋灭亡后，中国进入东晋南北朝的长期分裂。==北方从十六国混战走向北魏统一，南方东晋与宋齐梁陈相继更替，而民族交融与江南开发是这一时期最深的两条暗线。==", "learn": [{"h": "东晋与南朝", "p": "**317年**司马睿建立**东晋**，以建康为都；东晋偏安江南，门阀士族专权。**420年**起南方进入**南朝**，依次是**宋、齐、梁、陈**。\n\n==南朝记顺序：宋齐梁陈，四朝都在南方、都城都在建康一带。=="}, {"h": "十六国与北魏统一北方", "p": "西晋灭亡后北方进入**十六国**时期，各族政权并立混战。**439年**，鲜卑族建立的**北魏**统一北方，结束了北方长期分裂混战局面。\n\n==439年北魏统一北方，是孝文帝改革的前提：先有统一，才谈得上系统改革。=="}, {"h": "北魏孝文帝改革", "p": "孝文帝推行汉化改革：**494年**迁都**洛阳**；要求鲜卑贵族穿汉服、说汉语、改汉姓、与汉族通婚，并改革官制、推行**均田制**等。\n\n==孝文帝改革的核心判断：它加速了北方民族交融，也促进了北魏政权的封建化。=="}, {"h": "江南地区的开发", "p": "北方人口大量南迁（**北人南迁**），带来劳动力与先进生产技术；南方战乱较少、社会相对安定，统治者也重视发展。**江南地区**的农业、手工业和商业发展，经济重心开始南移的趋势出现。\n\n==江南开发记三因：人来了（劳动力）、技术来了、环境相对安定。=="}], "pitfalls": ["南朝顺序记错（宋齐梁陈）。", "把北魏统一北方（439年）与隋统一全国（589年）混淆。", "孝文帝改革只记迁都，漏掉汉服、汉语、汉姓、通婚等成套措施。"], "svg": "<rect x='15' y='20' width='160' height='34' rx='6' fill='#e0f2fe'/><text x='95' y='42' text-anchor='middle' font-size='12'>北方：北魏 439 统一</text><rect x='210' y='20' width='160' height='34' rx='6' fill='#e0f2fe'/><text x='290' y='42' text-anchor='middle' font-size='12'>南方：宋齐梁陈</text><rect x='105' y='80' width='175' height='34' rx='6' fill='#dbeafe'/><text x='192' y='102' text-anchor='middle' font-size='12'>交融 + 江南开发</text>", "svgCap": "南北分裂格局下，交融与开发同步推进。"}, "video": {"bvid": "BV1kh4y1T7Sm", "p": 1, "t": "第5课：三国两晋南北朝的政权更迭与民族交融（源史社会）", "dur": "1:08:42", "from": 0, "vtop": ["鼎立三年份：220魏、221蜀、229吴；西晋280统一、316灭亡。", "内迁是交融的起点，孝文帝改革是交融的高潮，江南开发靠北人南迁。", "439年只是北魏统一北方，589年才是隋统一全国，别混。"], "vsum": "第5课分南北两线看：北方从**三国鼎立**（220魏、221蜀、229吴）到西晋短暂统一（280统一、316灭亡），匈奴、鲜卑、羯、氐、羌内迁埋下交融种子；西晋亡后北方**十六国**混战，439年**北魏**统一北方，孝文帝迁都洛阳==推行汉化改革，加速民族交融==；南方东晋与宋、齐、梁、陈相继，北人南迁带来劳动力与技术，江南得到开发。视频为源史社会纲要上第5课精讲（1:08:42）。\n易错提醒：439年只是北魏统一北方，全国统一要到589年隋灭陈，两个年份和事件千万别对错位。", "vtech": ["看到政权更迭题 → 先画时间轴：鼎立（220/221/229）→西晋统一（280）→分裂（316后）→北魏统一北方（439）。", "看到改革措施材料 → 先归类（服饰/语言/姓氏/婚姻）再答共同指向，不要逐条抄材料。", "看到开发类问题 → 按人、技术、环境三因组织：北人南迁、技术传入、南方安定。"], "vgaokao": []}}, "hist_h011": {"name": "隋的兴亡与唐的盛世", "sec": 3, "secTitle": "从隋唐盛世到五代十国", "page": null, "desc": "581建隋、589统一、618隋亡唐立；大运河、贞观之治、开元盛世、民族交融与对外开放。", "criteria": ["能复述本节核心史实与时间", "能看懂案例史料的解读过程", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清史料依据"], "diag": null, "pre": [], "next": ["hist_h012"], "content": {"advance": {"a": "短命：581年建、618年亡，不到四十年，炀帝役重刑酷激起起义。功大：完成统一、开通大运河、创立并发展科举与三省六部等制度，为唐朝盛世奠定基础。评价王朝要把存续长短与制度遗产分开。", "kind": "self", "q": "隋朝短命而功大，这句话怎么理解？"}, "apply": [{"ans": 2, "opts": ["长安", "涿郡", "洛阳", "余杭"], "q": "大运河的中心是（ ）", "why": "大运河以洛阳为中心，北抵涿郡、南至余杭。"}, {"ans": 0, "opts": ["天可汗", "单于", "赞普", "可汗"], "q": "唐太宗被周边各族尊奉为（ ）", "why": "唐击败东突厥后，各族君长尊唐太宗为天可汗。"}], "basics": [{"ans": 1, "opts": ["581年", "589年", "618年", "626年"], "q": "隋朝完成统一是在（ ）", "why": "589年隋灭陈，完成统一。"}, {"ans": 1, "opts": ["唐高祖时期", "唐太宗时期", "武则天时期", "唐玄宗时期"], "q": "「贞观之治」出现在（ ）", "why": "唐太宗李世民在位期间出现贞观之治。"}], "case": {"a": "大运河加强了南北交通与经济联系、巩固了统一，但工程浩大、役重民困，也是隋朝速亡的重要原因。", "hints": ["先提取信息：纵贯南北、连接水系、物资北运、城镇兴起。", "再分经济与政治两面作答。"], "q": "材料（大意，据教材整理）：隋代开通的大运河纵贯南北，连接五大水系，沿线城镇兴起，南方的粮食与物资可大量北运。结合所学，说明大运河开通的影响。", "steps": ["经济上促进南北经济交流，南方粮食物资支援北方与都城、边防。", "政治上有利于巩固统一、加强中央对地方尤其是南方的控制。", "也要看到开通耗费巨大人力物力，加重人民负担，成为隋亡因素之一。"], "talk": ["影响类题用「促进/有利于」分条，同时别漏负面代价，评价才完整。"], "title": "案例：从大运河材料看沟通南北"}, "intro": "从581年建隋到唐前期盛世，中国再次走向统一与强盛。==隋的统一与大运河是地基，唐的贞观之治与开元盛世是高楼，民族交融与对外开放则让这个盛世有了更宽的边界。==", "learn": [{"h": "隋的建立与统一", "p": "**581年**杨坚建立**隋朝**，**589年**隋灭**陈**，完成统一，结束了长期分裂。隋文帝励精图治，隋炀帝时期开通**大运河**、营建东都等，劳民过度。\n\n==589年是南北分裂结束的年份，与439年北魏只统一北方严格区分。=="}, {"h": "大运河", "p": "**大运河**以**洛阳**为中心，北抵**涿郡**，南至**余杭**，由永济渠、通济渠、邗沟、江南河等河段连接海河、黄河、淮河、长江、钱塘江五大水系。\n\n==大运河记四点：中心洛阳、两端涿郡余杭、作用是南北交通与经济交流大动脉。=="}, {"h": "唐的建立与贞观之治", "p": "**618年**李渊建立**唐朝**；**626年****玄武门之变**后李世民即位。他吸取隋亡教训，轻徭薄赋、虚心纳谏、完善制度，出现**贞观之治**。其后武则天时期继续发展，到唐玄宗前期出现**开元盛世**。\n\n==贞观之治的关键词不是「强硬」，而是吸取隋亡教训后的休整与纳谏。=="}, {"h": "民族交融与对外交往", "p": "唐朝民族政策较开明：击败东突厥后尊唐太宗为**天可汗**，与**吐蕃**和亲（如文成公主入藏）、设机构管辖边疆。唐朝对外开放，长安是国际性大都市，与日本、新罗、天竺、波斯、大食等往来频繁。\n\n==盛世不只看疆域与赋税，还看它能不能容纳不同民族与外来文化。=="}], "pitfalls": ["581建隋、589统一、618隋亡三个年份串错。", "大运河中心记成长安（中心是洛阳）。", "把开元盛世记到唐太宗名下（开元是唐玄宗前期）。"], "svg": "<rect x='10' y='35' width='85' height='36' rx='6' fill='#e0f2fe'/><text x='52' y='58' text-anchor='middle' font-size='12'>581 建隋</text><rect x='105' y='35' width='85' height='36' rx='6' fill='#e0f2fe'/><text x='147' y='58' text-anchor='middle' font-size='12'>589 统一</text><rect x='200' y='35' width='85' height='36' rx='6' fill='#e0f2fe'/><text x='242' y='58' text-anchor='middle' font-size='12'>618 唐立 / 隋亡</text><rect x='295' y='35' width='85' height='36' rx='6' fill='#dbeafe'/><text x='337' y='58' text-anchor='middle' font-size='12'>贞观 · 开元</text>", "svgCap": "隋唐盛世的时间链：581—589—618—贞观—开元。"}, "video": {"bvid": "BV1C8411y7ZB", "p": 1, "t": "第6课：从隋唐盛世到五代十国（源史社会）", "dur": "58:31", "from": 0, "vtop": ["隋唐时间链：581建隋、589统一、618隋亡唐立、626玄武门之变。", "大运河中心洛阳、两端涿郡与余杭；贞观是太宗、开元是玄宗前期。", "唐由盛转衰看755安史之乱：节度使、外重内轻、藩镇割据。"], "vsum": "第6课是盛与衰的一课两面：581年隋建立、589年统一全国，开通以洛阳为中心的**大运河**；618年唐建立后，经**贞观之治**到**开元盛世**，==民族交融与对外开放达到高峰==。但节度使坐大、外重内轻酿成755年安史之乱，唐由盛转衰、**藩镇割据**，875年黄巢起义再予重击，907年朱温灭唐，进入五代十国分裂时期。视频为源史社会纲要上第6课精讲（58:31）。\n易错提醒：隋朝大运河的中心是洛阳而不是长安，这是本课最常被记错的一点。", "vtech": ["看到大运河题 → 四点定位：中心、两端、沟通水系、影响（交流与统一为正、役重为负）。", "看到由盛转衰题 → 先找制度病根（节度使与外重内轻），再写事件（755）与后果（藩镇割据）。", "看到灭亡类问题 → 分清转折点与终结点：755是转折，907朱温灭唐才是终结。"], "vgaokao": []}}, "hist_h012": {"name": "安史之乱与五代十国", "sec": 4, "secTitle": "从隋唐盛世到五代十国", "page": null, "desc": "755安史之乱与藩镇割据；875黄巢起义；907朱温灭唐与五代十国。", "criteria": ["能复述本节核心史实与时间", "能看懂案例史料的解读过程", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清史料依据"], "diag": null, "pre": ["hist_h011"], "next": [], "content": {"advance": {"a": "安史之乱后唐朝还延续约一个半世纪，但经济重心、财政、军事与中央权威都发生不可逆转的衰落，藩镇割据成常态；直接灭唐的是907年朱温。转折点看趋势改变，灭亡看政权终结，两者不能等同。", "kind": "self", "q": "为什么说安史之乱是唐朝由盛转衰的转折点，而不是唐朝灭亡的直接事件？"}, "apply": [{"ans": 0, "opts": ["藩镇割据", "三省六部完善", "科举兴盛", "天可汗体制形成"], "q": "安史之乱后唐朝政治上最突出的局面是（ ）", "why": "乱后节度使与藩镇割据，中央集权削弱。"}, {"ans": 2, "opts": ["755年", "763年", "875年", "907年"], "q": "黄巢起义爆发于（ ）", "why": "875年黄巢起义爆发，后攻入长安，打击唐统治。"}], "basics": [{"ans": 1, "opts": ["626年", "755年", "780年", "875年"], "q": "安史之乱爆发于（ ）", "why": "755年安禄山、史思明发动叛乱。"}, {"ans": 2, "opts": ["安禄山", "黄巢", "朱温", "杨炎"], "q": "907年灭唐、建立后梁的是（ ）", "why": "907年朱温灭唐建后梁，五代十国开始。"}], "case": {"a": "危险在于地方权力过度集中而中央控制失效，为安史之乱与此后藩镇割据埋下根源。", "hints": ["先拆权力：军、政、财三权集于一人。", "再看对比：地方强、中央弱，就是外重内轻。"], "q": "材料（大意，据教材整理）：唐后期节度使既掌兵权，又兼管地方行政与财政，部下只知节度使、不知朝廷，中央禁军反而空虚。结合所学，分析这种局面为什么危险。", "steps": ["节度使权力不受有效节制，容易拥兵自重、割据叛乱。", "中央军力与财力相对削弱，无法有效控制地方。", "安史之乱后藩镇割据长期化，正是这一格局的后果。"], "talk": ["制度风险题抓权力结构：谁的权变大、谁的权变小，危险自然说清。"], "title": "案例：从节度使权力读外重内轻"}, "intro": "唐朝的转折点是安史之乱。==节度使权力膨胀、外重内轻的格局埋下祸根，黄巢起义再给唐朝致命一击，907年唐亡后中国进入五代十国的分裂时期。==", "learn": [{"h": "安史之乱的背景", "p": "唐玄宗后期，边镇设**节度使**，集军、政、财大权于一身，形成**外重内轻**局面；朝政又日趋腐败。**755年**，安禄山与史思明发动叛乱，即**安史之乱**，**763年**才基本平定。\n\n==安史之乱记背景三词：节度使、外重内轻、玄宗后期腐败。=="}, {"h": "安史之乱的影响", "p": "安史之乱使北方经济遭到严重破坏，唐朝由盛转衰；乱后形成**藩镇割据**局面，中央集权被削弱，边疆形势与财政都持续恶化。\n\n==755年是唐史分水岭：此前是盛世扩张，此后是衰落与割据。=="}, {"h": "黄巢起义与唐的灭亡", "p": "唐后期土地兼并严重、赋税沉重，**875年**爆发**黄巢起义**，起义军一度攻入长安，沉重打击唐朝统治。**907年**，**朱温**灭唐，建立后梁，唐朝灭亡。\n\n==唐亡记链条：藩镇割据削弱中央，黄巢起义打击根基，朱温最后灭唐。=="}, {"h": "五代十国", "p": "**907—960年**北方相继更替**后梁、后唐、后晋、后汉、后周**五代，南方与山西等地并立十国左右，史称**五代十国**。这一时期政权更迭频繁，但统一趋势也在孕育，后周改革为北宋统一奠基。\n\n==五代在北方、十国多在南方；分裂是表象，走向再统一是趋势。=="}], "pitfalls": ["755安史之乱、875黄巢起义、907唐亡三个年份混淆。", "把藩镇割据说成安史之乱之前的主要局面（它是乱后长期化的结果）。", "五代顺序记错（后梁、后唐、后晋、后汉、后周）。"], "svg": "<rect x='10' y='35' width='85' height='36' rx='6' fill='#e0f2fe'/><text x='52' y='58' text-anchor='middle' font-size='12'>755 安史之乱</text><rect x='105' y='35' width='85' height='36' rx='6' fill='#e0f2fe'/><text x='147' y='58' text-anchor='middle' font-size='12'>藩镇割据</text><rect x='200' y='35' width='85' height='36' rx='6' fill='#e0f2fe'/><text x='242' y='58' text-anchor='middle' font-size='12'>875 黄巢起义</text><rect x='295' y='35' width='85' height='36' rx='6' fill='#dbeafe'/><text x='337' y='58' text-anchor='middle' font-size='12'>907 唐亡</text>", "svgCap": "唐由盛转衰到灭亡的因果链。"}, "video": {"bvid": "BV1C8411y7ZB", "p": 1, "t": "第6课：从隋唐盛世到五代十国（源史社会）", "dur": "58:31", "from": 0, "vtop": ["隋唐时间链：581建隋、589统一、618隋亡唐立、626玄武门之变。", "大运河中心洛阳、两端涿郡与余杭；贞观是太宗、开元是玄宗前期。", "唐由盛转衰看755安史之乱：节度使、外重内轻、藩镇割据。"], "vsum": "第6课是盛与衰的一课两面：581年隋建立、589年统一全国，开通以洛阳为中心的**大运河**；618年唐建立后，经**贞观之治**到**开元盛世**，==民族交融与对外开放达到高峰==。但节度使坐大、外重内轻酿成755年安史之乱，唐由盛转衰、**藩镇割据**，875年黄巢起义再予重击，907年朱温灭唐，进入五代十国分裂时期。视频为源史社会纲要上第6课精讲（58:31）。\n易错提醒：隋朝大运河的中心是洛阳而不是长安，这是本课最常被记错的一点。", "vtech": ["看到大运河题 → 四点定位：中心、两端、沟通水系、影响（交流与统一为正、役重为负）。", "看到由盛转衰题 → 先找制度病根（节度使与外重内轻），再写事件（755）与后果（藩镇割据）。", "看到灭亡类问题 → 分清转折点与终结点：755是转折，907朱温灭唐才是终结。"], "vgaokao": []}}, "hist_h013": {"name": "选官与中枢：科举制和三省六部制", "sec": 5, "secTitle": "隋唐制度的变化与创新", "page": null, "desc": "隋创科举、唐完善；中书出令、门下审令、尚书行令与吏户礼兵刑工六部。", "criteria": ["能复述本节核心史实与时间", "能看懂案例史料的解读过程", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清史料依据"], "diag": null, "pre": [], "next": ["hist_h014"], "content": {"advance": {"a": "共同服务于中央集权与皇权加强：科举把选官权收归中央、削弱世家；三省分相权、使决策执行受皇权控制。两项制度都让王朝机器更可控、更耐用。", "kind": "self", "q": "科举制和三省六部制，一个向外选人、一个向内分权，它们共同服务于什么？"}, "apply": [{"ans": 1, "opts": ["吏部", "户部", "礼部", "兵部"], "q": "六部中主管财政的是（ ）", "why": "户部主管户籍、财政。"}, {"ans": 2, "opts": ["隋文帝", "唐太宗", "武则天", "唐玄宗"], "q": "首创殿试、提高科举地位的统治者是（ ）", "why": "武则天首创殿试与武举。"}], "basics": [{"ans": 1, "opts": ["孝廉科", "进士科", "明经科", "武举"], "q": "科举制正式形成的标志是隋炀帝设（ ）", "why": "隋炀帝设进士科，科举制正式形成。"}, {"ans": 1, "opts": ["中书省", "门下省", "尚书省", "吏部"], "q": "三省中负责审核诏令的是（ ）", "why": "门下省负责审核封驳诏令。"}], "case": {"a": "意义在于以考试选官取代门第选官，扩大统治基础、提高官员素质，并促进教育与社会流动。", "hints": ["先对比旧制：九品中正制重门第，世家垄断。", "再看新制标准：考试成绩。"], "q": "材料（大意，据教材整理）：隋炀帝设进士科，士人可凭诗赋经义考试入仕，不再完全依靠门第与推荐。结合所学，说明这一变化的意义。", "steps": ["选官标准由门第转向才能，读书人入仕通道打开。", "世家大族垄断仕途的局面被打破，统治基础扩大。", "政府能选拔有文化才能的官员，行政与文化都受益。"], "talk": ["选官题永远先问标准变没变：从出身到考试，是科举题的题眼。"], "title": "案例：从进士科材料看选官之变"}, "intro": "隋唐制度最耐用的两项遗产，是选官的科举制和中枢的三省六部制。==科举把选官从拼出身改成拼考试，三省六部把皇权下的行政拆成分工制衡的机器，两者都影响中国上千年。==", "learn": [{"h": "科举制的创立与发展", "p": "隋文帝开始分科考试选官，**隋炀帝**时设**进士科**，**科举制**正式形成。唐朝加以完善：唐太宗扩充国学规模，**武则天**首创**殿试**与武举，唐玄宗时诗赋成为进士科主要内容。\n\n==科举记源头：隋创立、唐完善，不要说成唐朝发明。=="}, {"h": "科举制的影响", "p": "科举以考试成绩取人，打破了**九品中正制**下世家大族垄断仕途的局面，扩大了统治基础，提高了官员文化素质，并促进了社会流动与教育、文学发展。\n\n==评价科举先抓一个词：相对公平的考试选拔，标准从出身转向才能。=="}, {"h": "三省六部制的结构", "p": "**三省**是**中书省**（起草诏令）、**门下省**（审核封驳）、**尚书省**（执行），尚书省下设**六部**：**吏、户、礼、兵、刑、工**，分管人事、财政、礼仪、军事、司法、工程。\n\n==三省记分工口诀：中书出令、门下审令、尚书行令；六部按吏户礼兵刑工顺序记。=="}, {"h": "三省六部制的意义", "p": "三省之间既分工又制衡，提高了行政效率，也使相权被分割、皇权进一步加强。这套体制在隋唐正式确立，成为后世王朝中央官制的基本框架。\n\n==三省六部的双重效果要同记：效率提高与皇权加强，是同一枚硬币的两面。=="}], "pitfalls": ["把科举制说成唐朝创立（隋创立、唐完善）。", "三省分工张冠李戴（中书出令、门下审令、尚书执行）。", "把察举制、九品中正制与科举制的先后与标准混为一谈。"], "svg": "<rect x='10' y='20' width='110' height='34' rx='6' fill='#e0f2fe'/><text x='65' y='42' text-anchor='middle' font-size='12'>中书省 出令</text><rect x='140' y='20' width='110' height='34' rx='6' fill='#e0f2fe'/><text x='195' y='42' text-anchor='middle' font-size='12'>门下省 审令</text><rect x='270' y='20' width='110' height='34' rx='6' fill='#e0f2fe'/><text x='325' y='42' text-anchor='middle' font-size='12'>尚书省 行令</text><rect x='80' y='78' width='230' height='30' rx='6' fill='#dbeafe'/><text x='195' y='98' text-anchor='middle' font-size='12'>六部：吏 户 礼 兵 刑 工</text>", "svgCap": "三省分工与六部构成。"}, "video": {"bvid": "BV1J9tHesEYa", "p": 1, "t": "第7课：隋唐制度的变化与创新", "dur": "31:46", "from": "小马历史课堂", "vtop": ["科举隋创唐完善，选官标准从门第转向考试；三省分工：中书出令、门下审令、尚书行令。", "租庸调以人丁为本（租粮、调绢布、庸力役），两税法以资产土地为本。", "780年两税法是赋税史转折：杨炎建议、德宗实行、夏秋两征。"], "vsum": "第7课讲两项长命制度与一次赋税大变：选官上，隋创**科举**（炀帝设进士科）、唐完善，打破门第垄断；中枢上，**三省六部制**以中书出令、门下审令、尚书执行、六部分工，既提效率又分相权、强皇权。赋税上，唐前期**租庸调制**以人丁为本，均田制破坏后难以为继，780年杨炎==两税法改以资产与土地为主要依据==、夏秋两征，影响此后近千年。视频为小马历史课堂纲要上第7课精讲（31:46，本站自存版），内容覆盖隋唐部分：科举、三省六部与两税法；宋朝分割相权一节视频未涵盖，看本站正文节点。\n易错提醒：科举制是隋朝创立、唐朝完善的，把它说成唐朝创立是最常见的丢分点。", "vtech": ["看到选官题 → 先问标准：推荐看门第还是考试定去取，一秒定制度名。", "看到三省题 → 按流程答：谁起草、谁审核、谁执行，顺序不能乱。", "看到赋税题 → 先比标准（人丁还是资产土地），再比次数与时间，780年是题眼。"], "vgaokao": []}}, "hist_h014": {"name": "赋税之变：从租庸调制到两税法", "sec": 6, "secTitle": "隋唐制度的变化与创新", "page": null, "desc": "租庸调以人丁为本；780年杨炎两税法转向资产与土地、夏秋两征。", "criteria": ["能复述本节核心史实与时间", "能看懂案例史料的解读过程", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清史料依据"], "diag": null, "pre": ["hist_h013"], "next": [], "content": {"advance": {"a": "相对而言，无地少地的农民不再按丁承担全额，负担有所减轻，纳税面也更公平；但地主可转嫁负担、后期又有附加税，农民负担并未根本解决。评价税制改革要看标准变化与实际执行两层。", "kind": "self", "q": "两税法减轻农民负担了吗？为什么评价它不能只说好或坏？"}, "apply": [{"ans": 1, "opts": ["科举制完善", "均田制破坏、租庸调制难以为继", "大运河开通", "五代十国分裂"], "q": "两税法实行的根本背景是（ ）", "why": "均田制破坏、土地兼并与户籍混乱使按丁征税失去基础。"}, {"ans": 2, "opts": ["房玄龄", "魏征", "杨炎", "姚崇"], "q": "提出两税法建议的宰相是（ ）", "why": "780年宰相杨炎提出两税法。"}], "basics": [{"ans": 1, "opts": ["755年", "780年", "875年", "907年"], "q": "两税法实行于（ ）", "why": "780年杨炎建议、唐德宗实行两税法。"}, {"ans": 2, "opts": ["缴纳粮食", "缴纳绢布", "服徭役或纳绢代役", "缴纳货币"], "q": "租庸调制中「庸」指的是（ ）", "why": "庸指徭役，规定每年服役二十天，可纳绢代役。"}], "case": {"a": "最大不同是征税标准：由以人丁为主转为以资产、土地为主，这是赋税制度的重大变化。", "hints": ["先找关键词：资产、田亩、居住地、两次。", "再与租庸调的丁男授田前提对比。"], "q": "材料（大意，据教材整理）：两税法规定，无论主户客户，按居住地登记，按资产多少与田亩定税，分夏秋两次缴纳。结合所学，指出它与租庸调制最大的不同。", "steps": ["租庸调以人丁为征税主体，前提是均田制与户籍稳定。", "两税法以资产和土地为主要依据，户籍失序下也能组织收入。", "征收时间与方式也变了：由分散多项改为夏秋两税合并征收。"], "talk": ["赋税题先比标准：按人还是按地按产，这是两税法题的题眼。"], "title": "案例：从征税标准读两税法"}, "intro": "赋税制度为什么会变？因为土地和人口的实际情况变了。==从租庸调制到两税法，是唐朝赋税从按人征税转向按资产与土地征税的一次大转弯，780年是必须钉牢的年份。==", "learn": [{"h": "租庸调制的内容", "p": "唐前期在**均田制**基础上实行**租庸调制**：受田丁男每年纳粟为**租**，纳绢布为**调**，服徭役为**庸**（每年服役二十天，不服役可纳绢代役）。\n\n==租庸调记三字对应：租是粮、调是绢布、庸是力役（可纳绢代役）。=="}, {"h": "旧制为什么行不通", "p": "安史之乱后人口大量流散、户口登记混乱，**土地兼并**加剧、**均田制**遭到破坏，按丁征税的租庸调制失去了实施基础，国家财政又急需收入。\n\n==赋税改革的原因永远先找基础崩没崩：均田坏了、户籍乱了，旧税就收不上来。=="}, {"h": "两税法的内容", "p": "**780年**，唐德宗采纳宰相**杨炎**建议实行**两税法**：按人丁与资产征收地税、户税，分为夏、秋两次征收；居住地纳税，税额按资产和土地多少确定。\n\n==两税法记转变：从以人丁为主，到以资产、土地为主。=="}, {"h": "两税法的影响", "p": "两税法扩大了纳税面、增加了财政收入，在一定程度上减轻了无地少地农民的负担；它也标志着赋税标准的历史性变化，影响此后近千年的赋税制度。\n\n==评价两税法抓两点：财政增收与征税标准之变，不要说成农民负担从此消失。=="}], "pitfalls": ["780年两税法与755年安史之乱年份混淆。", "租、调、庸三项对应物记反（租粮、调绢布、庸力役）。", "把两税法说成按人头平均征税（恰恰相反，它转向资产与土地）。"], "svg": "<rect x='15' y='30' width='160' height='40' rx='6' fill='#e0f2fe'/><text x='95' y='48' text-anchor='middle' font-size='12'>租庸调制</text><text x='95' y='64' text-anchor='middle' font-size='11'>以人丁为本</text><rect x='215' y='30' width='160' height='40' rx='6' fill='#dbeafe'/><text x='295' y='48' text-anchor='middle' font-size='12'>两税法 780</text><text x='295' y='64' text-anchor='middle' font-size='11'>以资产土地为本</text><line x1='175' y1='50' x2='215' y2='50' stroke='#94a3b8'/>", "svgCap": "赋税标准之变：人丁本位到资产土地本位。"}, "video": {"bvid": "BV1J9tHesEYa", "p": 1, "t": "第7课：隋唐制度的变化与创新", "dur": "31:46", "from": "小马历史课堂", "vtop": ["科举隋创唐完善，选官标准从门第转向考试；三省分工：中书出令、门下审令、尚书行令。", "租庸调以人丁为本（租粮、调绢布、庸力役），两税法以资产土地为本。", "780年两税法是赋税史转折：杨炎建议、德宗实行、夏秋两征。"], "vsum": "第7课讲两项长命制度与一次赋税大变：选官上，隋创**科举**（炀帝设进士科）、唐完善，打破门第垄断；中枢上，**三省六部制**以中书出令、门下审令、尚书执行、六部分工，既提效率又分相权、强皇权。赋税上，唐前期**租庸调制**以人丁为本，均田制破坏后难以为继，780年杨炎==两税法改以资产与土地为主要依据==、夏秋两征，影响此后近千年。视频为小马历史课堂纲要上第7课精讲（31:46，本站自存版），内容覆盖隋唐部分：科举、三省六部与两税法；宋朝分割相权一节视频未涵盖，看本站正文节点。\n易错提醒：科举制是隋朝创立、唐朝完善的，把它说成唐朝创立是最常见的丢分点。", "vtech": ["看到选官题 → 先问标准：推荐看门第还是考试定去取，一秒定制度名。", "看到三省题 → 按流程答：谁起草、谁审核、谁执行，顺序不能乱。", "看到赋税题 → 先比标准（人丁还是资产土地），再比次数与时间，780年是题眼。"], "vgaokao": []}}, "hist_h015": {"name": "三国至隋唐的思想与科技", "sec": 7, "secTitle": "三国至隋唐的文化", "page": null, "desc": "儒学受挑战与韩愈复兴、三教并行；雕版印刷与火药、《唐本草》、赵州桥。", "criteria": ["能复述本节核心史实与时间", "能看懂案例史料的解读过程", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清史料依据"], "diag": null, "pre": [], "next": ["hist_h016"], "content": {"advance": {"a": "隋唐社会佛教、道教影响已深，强行独尊难以服众；三教并行既维护儒学正统与统治秩序，又笼络佛道势力、减少冲突，体现盛世统治的包容与自信。政策选择要联系社会现实，不只看皇帝喜好。", "kind": "self", "q": "为什么隋唐统治者要奉行三教并行，而不是再搞一次独尊儒术？"}, "apply": [{"ans": 1, "opts": ["董仲舒", "韩愈", "朱熹", "王阳明"], "q": "唐中期掀起儒学复兴运动、反对佞佛的是（ ）", "why": "韩愈掀起儒学复兴运动；朱熹是宋代。"}, {"ans": 0, "opts": ["李春", "宇文恺", "鲁班", "李冰"], "q": "赵州桥的设计建造者是隋朝工匠（ ）", "why": "隋朝李春建造赵州桥。"}], "basics": [{"ans": 2, "opts": ["《黄帝内经》", "《千金方》", "《唐本草》", "《本草纲目》"], "q": "世界上第一部由国家颁布的药典是（ ）", "why": "唐政府颁行的《唐本草》是世界第一部国家药典；《本草纲目》是明代李时珍所著。"}, {"ans": 0, "opts": ["《金刚经》", "《论语》刻本", "《唐本草》", "《千金方》"], "q": "现存最早的有确切日期的雕版印刷品是（ ）", "why": "868年印制的《金刚经》是现存最早标有确切日期的雕版印刷品。"}], "case": {"a": "雕版印刷使书籍得以批量复制，促进文化传播与教育发展，是唐朝科技的代表性成就。", "hints": ["先定位：868年、唐朝、雕版印刷。", "再想用途：佛经大量复制说明宗教传播与文化需求推动技术。"], "q": "材料（大意，据教材整理）：868年印制的《金刚经》卷首有精美扉画，末尾标有明确印制日期，是现存最早的有确切日期的雕版印刷品。结合所学，说明雕版印刷出现的影响。", "steps": ["雕版印刷提高了书籍复制效率，降低了传播成本。", "它促进了文化教育与佛教等思想的传播。", "它是中国对世界文明的重要贡献，后来外传影响世界。"], "talk": ["科技史料题先答是什么时代的技术，再答它改变了什么传播环节。"], "title": "案例：从《金刚经》印本看印刷术"}, "intro": "三国至隋唐，思想上儒学先受挑战再走向复兴，科技上则留下雕版印刷、火药等改变世界的发明。==这一节记两条线：儒、释、道三教并行是思想格局，科技成果要逐项对准时代与用途。==", "learn": [{"h": "儒学的挑战与复兴", "p": "魏晋南北朝时期，**佛教**盛行、**道教**传播，**儒学**的独尊地位受到冲击。隋唐时期统治者奉行**三教并行**政策，儒学仍居正统；唐中期**韩愈**掀起儒学复兴运动，反对佛教、维护儒家道统。\n\n==思想线记格局：不是一教独大，而是三教并行、儒学为正统并谋求复兴。=="}, {"h": "科技高峰：印刷与火药", "p": "唐朝时出现**雕版印刷**，现存最早的标有确切日期的雕版印刷品是868年印制的《金刚经》。**火药**由古代炼丹家在炼制丹药中发明，唐末已用于战争。\n\n==四大发明在本册只钉两项的时代：雕版印刷与火药都是唐朝，要与宋代的活字印刷、火药广泛应用区分。=="}, {"h": "医学、数学与其他成就", "p": "隋唐医学进步：孙思邈著**《千金方》**；唐政府颁行**《唐本草》**，是世界上第一部由国家颁布的药典。数学、天文、建筑也有突破，如隋朝工匠**李春**建造的**赵州桥**是现存最古老的石拱桥。\n\n==科技题爱考首创与之最：《唐本草》的国家颁布与世界第一部药典，是高频考点。=="}], "pitfalls": ["把活字印刷记到唐朝（活字印刷是北宋毕昇）。", "《唐本草》与《本草纲目》的时代与性质混淆。", "三教并行误解为三教地位完全平等取代儒学正统（儒学仍是正统）。"], "svg": "<rect x='10' y='30' width='110' height='36' rx='6' fill='#e0f2fe'/><text x='65' y='53' text-anchor='middle' font-size='12'>三教并行</text><rect x='140' y='30' width='110' height='36' rx='6' fill='#e0f2fe'/><text x='195' y='53' text-anchor='middle' font-size='12'>雕版印刷 · 火药</text><rect x='270' y='30' width='110' height='36' rx='6' fill='#dbeafe'/><text x='325' y='53' text-anchor='middle' font-size='12'>《唐本草》</text>", "svgCap": "思想格局与科技成就一览。"}, "video": {"bvid": "BV1nV411w71C", "p": 1, "t": "第8课：三国至隋唐的文化（源史社会）", "dur": "34:42", "from": 0, "vtop": ["思想格局是三教并行、儒学为正统，韩愈在唐中期复兴儒学。", "科技只钉唐朝两项发明：雕版印刷与火药；《唐本草》是世界第一部国家药典。", "交流记方向：遣唐使来学、玄奘西行、鉴真东渡。"], "vsum": "第8课是文化总览：思想上儒学受佛道挑战、隋唐**三教并行**，韩愈复兴儒学；科技上唐朝出现**雕版印刷**与火药（唐末用于战争），**《唐本草》**为世界第一部国家药典，赵州桥为建筑典范。文学艺术上唐诗（李白、杜甫、白居易）、书法（颜真卿、柳公权）、绘画（吴道子）与敦煌莫高窟熠熠生辉；对外交流上遣唐使来学、==玄奘西行取经、鉴真东渡传法==，尽显开放气象。视频为源史社会纲要上第8课精讲（34:42）。\n易错提醒：玄奘是西行去天竺取经、鉴真是东渡去日本传法，两个人的方向千万别记反。", "vtech": ["看到文化成就题 → 先分门类（思想/科技/文学/书画/交流）再对人物作品，防张冠李戴。", "看到交流题 → 先定方向（来学、西行、东渡）再答内容与影响。", "看到首创之最题 → 核对时代：《唐本草》唐、活字印刷宋、《本草纲目》明，跨代即错。"], "vgaokao": []}}, "hist_h016": {"name": "三国至隋唐的文学艺术与中外交流", "sec": 8, "secTitle": "三国至隋唐的文化", "page": null, "desc": "唐诗李杜白、书法颜柳、绘画吴道子、莫高窟；遣唐使与玄奘、鉴真。", "criteria": ["能复述本节核心史实与时间", "能看懂案例史料的解读过程", "能独立做对基础题", "能独立做对应用题", "能独立做对综合题并讲清史料依据"], "diag": null, "pre": ["hist_h015"], "next": [], "content": {"advance": {"a": "政治上长期分裂中各政权竞争、统一王朝又强盛开放；民族交融带来成分多元；佛教等外来文化传入并本土化；对外交通发达。文化气象从来是政治、民族与交通条件的综合结果。", "kind": "self", "q": "三国至隋唐文化为什么呈现开放与多元并存的气象？"}, "apply": [{"ans": 0, "opts": ["《大唐西域记》", "《佛国记》", "《徐霞客游记》", "《马可·波罗行纪》"], "q": "玄奘西行求法归国后所著、记载西域见闻的是（ ）", "why": "玄奘著《大唐西域记》；《佛国记》为东晋法显所著。"}, {"ans": 0, "opts": ["颜真卿、柳公权的楷书", "顾恺之的绘画", "赵孟頫的书法", "郑板桥的书画"], "q": "下列属于唐朝书法成就的是（ ）", "why": "颜真卿、柳公权是唐代楷书名家；赵孟頫为元代。"}], "basics": [{"ans": 1, "opts": ["李白", "杜甫", "白居易", "王维"], "q": "被誉为「诗圣」、作品被称为「诗史」的是（ ）", "why": "杜甫诗反映社会现实，被称为诗圣、诗史。"}, {"ans": 1, "opts": ["玄奘", "鉴真", "法显", "义净"], "q": "东渡日本传播唐文化的高僧是（ ）", "why": "鉴真东渡日本传播唐文化；玄奘是西行天竺。"}], "case": {"a": "原因是唐朝强盛开放、文化先进，日本希望通过学习唐制推动自身发展，遣唐使正是这一交流的载体。", "hints": ["先想唐朝有什么值得学：强盛、制度先进、文化繁荣。", "再想日本的需求：改革与发展需要样本。"], "q": "材料（大意，据教材整理）：日本在两百多年间多次派遣唐使，人数众多，使团成员回国后把唐朝的典章制度、文化习俗带回日本。结合所学，说明遣唐使频繁来华的原因。", "steps": ["唐朝国力强盛、文化先进，对周边有强大吸引力。", "日本正谋求改革发展，需要全面学习唐的制度与文化。", "唐朝开放包容的对外政策为遣唐使来华提供了条件。"], "talk": ["交流题答原因用推拉两面：唐的吸引力（拉）加对方的需求（推）。"], "title": "案例：从遣唐使读唐文化的辐射力"}, "intro": "唐诗的天空、书画的高峰、石窟的宝库，再加上遣唐使、玄奘与鉴真的脚步，共同构成三国至隋唐文化的开放气象。==文学艺术记代表人物与作品，中外交流记方向：谁来学、谁去传。==", "learn": [{"h": "文学：唐诗的黄金时代", "p": "唐朝诗歌最盛：**李白**诗风浪漫豪迈，被称为「诗仙」；**杜甫**诗风沉郁顿挫、反映社会现实，被称为「诗圣」，其诗有「诗史」之称；**白居易**主张诗歌反映现实、通俗易懂。\n\n==唐诗记三人三标签：李白浪漫、杜甫现实、白居易通俗写实。=="}, {"h": "书法、绘画与石窟", "p": "书法名家辈出：**颜真卿、柳公权**的楷书各成一体（颜筋柳骨）。绘画有**吴道子**（被誉为「画圣」）。佛教石窟艺术延续发展，此前开凿的**云冈石窟、龙门石窟**闻名于世，**敦煌莫高窟**保存了大量壁画与塑像，是艺术宝库。\n\n==艺术题先分门类再对人物：书法颜柳、绘画吴道子、石窟看莫高窟。=="}, {"h": "中外交流：遣唐使与玄奘、鉴真", "p": "唐朝对外开放：日本多次派**遣唐使**来华学习制度与文化；高僧**玄奘**西行天竺取经，著《大唐西域记》；**鉴真**东渡日本，传播唐文化。长安汇聚各国使节、商人与留学生。\n\n==交流记方向：遣唐使是来学，玄奘是去取经求学，鉴真是去传播，三者不要混方向。=="}], "pitfalls": ["玄奘（西行天竺）与鉴真（东渡日本）方向记反。", "李白浪漫、杜甫现实的风格标签对错位。", "把莫高窟说成唐朝始建（始建于前秦时期，隋唐大盛、保存最丰）。"], "svg": "<rect x='10' y='30' width='110' height='36' rx='6' fill='#e0f2fe'/><text x='65' y='53' text-anchor='middle' font-size='12'>唐诗 李杜白</text><rect x='140' y='30' width='110' height='36' rx='6' fill='#e0f2fe'/><text x='195' y='53' text-anchor='middle' font-size='12'>书画 颜柳吴</text><rect x='270' y='30' width='110' height='36' rx='6' fill='#dbeafe'/><text x='325' y='53' text-anchor='middle' font-size='12'>交流 玄奘鉴真</text>", "svgCap": "文学艺术与中外交流的代表符号。"}, "video": {"bvid": "BV1nV411w71C", "p": 1, "t": "第8课：三国至隋唐的文化（源史社会）", "dur": "34:42", "from": 0, "vtop": ["思想格局是三教并行、儒学为正统，韩愈在唐中期复兴儒学。", "科技只钉唐朝两项发明：雕版印刷与火药；《唐本草》是世界第一部国家药典。", "交流记方向：遣唐使来学、玄奘西行、鉴真东渡。"], "vsum": "第8课是文化总览：思想上儒学受佛道挑战、隋唐**三教并行**，韩愈复兴儒学；科技上唐朝出现**雕版印刷**与火药（唐末用于战争），**《唐本草》**为世界第一部国家药典，赵州桥为建筑典范。文学艺术上唐诗（李白、杜甫、白居易）、书法（颜真卿、柳公权）、绘画（吴道子）与敦煌莫高窟熠熠生辉；对外交流上遣唐使来学、==玄奘西行取经、鉴真东渡传法==，尽显开放气象。视频为源史社会纲要上第8课精讲（34:42）。\n易错提醒：玄奘是西行去天竺取经、鉴真是东渡去日本传法，两个人的方向千万别记反。", "vtech": ["看到文化成就题 → 先分门类（思想/科技/文学/书画/交流）再对人物作品，防张冠李戴。", "看到交流题 → 先定方向（来学、西行、东渡）再答内容与影响。", "看到首创之最题 → 核对时代：《唐本草》唐、活字印刷宋、《本草纲目》明，跨代即错。"], "vgaokao": []}}}, "units": {"u_hist_1": {"id": "u_hist_1", "name": "中华文明的起源与早期国家", "secs": "第1课", "pageFrom": null, "pageTo": null, "members": ["hist_h001", "hist_h002"], "video": {"bvid": "BV1Uz4y1p752", "p": 1, "t": "第1课：中华文明的起源与早期国家（源史社会）", "dur": "40:14", "from": 0, "vtop": ["文明起源的特征是多元一体：多地起源、走向融合、中原为核心。", "仰韶种粟（黄河）、河姆渡种稻（长江），遗址要成对记。", "早期国家靠血缘组织：世袭、分封、宗法都是家国一体。"], "vsum": "第1课跨度最大：旧石器时代元谋人（约170万年）、北京人（会用火）打底，新石器时代农业革命后，仰韶（黄河中游、粟、彩陶）、大汶口、河姆渡（长江下游、水稻）==多点开花，形成多元一体格局==。进入早期国家阶段：夏行**世袭制**（二里头遗址），商有甲骨文与内外服制，西周靠**分封制**、**宗法制**（核心是**嫡长子继承制**）、礼乐制组织国家——共同特征是神权与王权结合、血缘为纽带、家国一体、地方控制松散。视频为源史社会纲要上第1课精讲（40:14）。\n易错提醒：宗法制的核心要答嫡长子继承制，只答「血缘关系」太笼统、不得分。", "vtech": ["看到两则不同地域的材料 → 先分别提取地点与关键物，再问「共同指向什么格局」。", "看到遗址配对题 → 按流域锁定：黄河—仰韶—粟，长江—河姆渡—稻。", "看到「早期国家特征」设问 → 从神权、血缘、集权程度、地方控制四点逐项找。"], "vgaokao": []}}, "u_hist_2": {"id": "u_hist_2", "name": "诸侯纷争与变法运动", "secs": "第2课", "pageFrom": null, "pageTo": null, "members": ["hist_h003", "hist_h004"], "video": {"bvid": "BV1Dp4y1375Q", "p": 1, "t": "第2课：诸侯纷争与变法运动（源史社会）", "dur": "55:07", "from": 0, "vtop": ["变法的根本原因是生产力发展（铁器牛耕），不是君主个人想法。", "商鞅变法三线：县制、废井田奖耕织、军功爵制。", "百家争鸣四家关键词：仁、无为、兼爱、法治。"], "vsum": "第2课的逻辑链：铁器牛耕→生产力提高→**井田制**瓦解、土地私有确立→周王室衰微、诸侯纷争→各国变法。**商鞅变法**是样本：政治（县制、什伍连坐、废世卿世禄）、经济（废井田开阡陌、奖励耕织、统一度量衡）、军事（**军功爵制**），==使秦富强并确立封建制度==。思想领域同步爆发**百家争鸣**：儒（仁、仁政、民贵君轻、隆礼重法）、道（无为）、墨（兼爱非攻）、法（以法治国）四家对照记忆。视频为源史社会纲要上第2课精讲（约55:07）。\n易错提醒：变法的根本原因是生产力发展与社会转型，「为了富国强兵」只是目标，不能当作原因来答。", "vtech": ["看到变法背景题 → 第一笔先写生产力（铁器牛耕）与土地制度变革，再写政治需求。", "看到学派辨认题 → 先抓关键词定派（仁/无为/兼爱/法），再比较同派内部差异。", "看到措施类材料 → 按措施→思想→目标→影响四层拆解。"], "vgaokao": []}}, "u_hist_3": {"id": "u_hist_3", "name": "秦统一多民族封建国家的建立", "secs": "第3课", "pageFrom": null, "pageTo": null, "members": ["hist_h005", "hist_h006"], "video": {"bvid": "BV1F94y1k7k4", "p": 1, "t": "第3课：秦统一多民族封建国家的建立（源史社会）", "dur": "49:42", "from": 0, "vtop": ["前221年秦统一，灭六国顺序：韩赵魏楚燕齐。", "中央集权三件套：皇帝制、三公九卿、郡县制。", "巩固四件套（文、币、衡、轨）是正面，焚书坑儒与暴政是反面。"], "vsum": "第3课分两半：统一与制度——前230至前221年灭六国（韩赵魏楚燕齐），==建立第一个统一的多民族封建国家==；**皇帝制**、**三公九卿制**（丞相行政、太尉军事、御史大夫监察）、**郡县制**构成中央集权蓝本，北击匈奴、南征百越拓展疆域。巩固与速亡——书同文（小篆）、币同制（半两钱）、衡同量、车同轨功在长远；焚书坑儒、严刑峻法、繁重徭役激化矛盾，前209年**大泽乡起义**、前207年秦亡。评价秦始皇必须两面看。视频为源史社会纲要上第3课精讲（49:42）。\n易错提醒：三公分工最容易记混，丞相管行政、太尉管军事、御史大夫管监察，御史大夫不是行政官。", "vtech": ["看到制度对比 → 用三格表：谁任命、能否世袭、与中央关系。", "看到原因分析 → 分层：导火索→统治政策→根本矛盾，最后一句史家评价收尾。", "看到评价人物 → 功过两面各列实据，禁止一边倒。"], "vgaokao": []}}, "u_hist_4": {"id": "u_hist_4", "name": "西汉与东汉——统一多民族封建国家的巩固", "secs": "第4课", "pageFrom": null, "pageTo": null, "members": ["hist_h007", "hist_h008"], "video": {"bvid": "BV1gu41177pa", "p": 1, "t": "第4课：西汉与东汉——统一多民族封建国家的巩固（源史社会）", "dur": "2:28:14", "from": 0, "vtop": ["大一统四线：政治推恩令、经济盐铁官营、思想独尊儒术、军事击匈奴通西域。", "东汉衰亡是条链：兼并→豪强→专权→黄巾起义。", "察举制不是科举制，刺史是监察不是行政长官。"], "vsum": "第4课是「巩固」的正反两面：西汉先有郡国并行与七国之乱的教训，再有文景之治的积累，==最终汉武帝四线推进大一统==（**推恩令**与刺史、盐铁官营与五铢钱、**独尊儒术**与太学、卫霍北击与张骞通西域）。东汉刘秀光武中兴（定都洛阳、柔道治国），但中后期土地兼并使豪强坐大、外戚宦官交替专权，184年**黄巾起义**后中央集权瓦解、军阀割据。视频为源史社会纲要上第4课精讲（2:28:14）。\n易错提醒：刺史是监察官，不是地方行政长官，别把刺史当成一级地方行政机构的长官。", "vtech": ["看到政策类材料 → 先找动作词（分、夺、监察）定政策名，再答特点与影响。", "看到衰亡类问题 → 先画因果链再动笔：兼并→豪强→专权→起义→割据。", "看到选官制度 → 先分时代：察举是汉代推荐制，科举是隋唐考试制，别跨代。"], "vgaokao": []}}, "u_hist_5": {"id": "u_hist_5", "name": "三国两晋南北朝的政权更迭与民族交融", "secs": "第5课", "pageFrom": null, "pageTo": null, "members": ["hist_h009", "hist_h010"], "video": {"bvid": "BV1kh4y1T7Sm", "p": 1, "t": "第5课：三国两晋南北朝的政权更迭与民族交融（源史社会）", "dur": "1:08:42", "from": 0, "vtop": ["鼎立三年份：220魏、221蜀、229吴；西晋280统一、316灭亡。", "内迁是交融的起点，孝文帝改革是交融的高潮，江南开发靠北人南迁。", "439年只是北魏统一北方，589年才是隋统一全国，别混。"], "vsum": "第5课分南北两线看：北方从**三国鼎立**（220魏、221蜀、229吴）到西晋短暂统一（280统一、316灭亡），匈奴、鲜卑、羯、氐、羌内迁埋下交融种子；西晋亡后北方**十六国**混战，439年**北魏**统一北方，孝文帝迁都洛阳==推行汉化改革，加速民族交融==；南方东晋与宋、齐、梁、陈相继，北人南迁带来劳动力与技术，江南得到开发。视频为源史社会纲要上第5课精讲（1:08:42）。\n易错提醒：439年只是北魏统一北方，全国统一要到589年隋灭陈，两个年份和事件千万别对错位。", "vtech": ["看到政权更迭题 → 先画时间轴：鼎立（220/221/229）→西晋统一（280）→分裂（316后）→北魏统一北方（439）。", "看到改革措施材料 → 先归类（服饰/语言/姓氏/婚姻）再答共同指向，不要逐条抄材料。", "看到开发类问题 → 按人、技术、环境三因组织：北人南迁、技术传入、南方安定。"], "vgaokao": []}}, "u_hist_6": {"id": "u_hist_6", "name": "从隋唐盛世到五代十国", "secs": "第6课", "pageFrom": null, "pageTo": null, "members": ["hist_h011", "hist_h012"], "video": {"bvid": "BV1C8411y7ZB", "p": 1, "t": "第6课：从隋唐盛世到五代十国（源史社会）", "dur": "58:31", "from": 0, "vtop": ["隋唐时间链：581建隋、589统一、618隋亡唐立、626玄武门之变。", "大运河中心洛阳、两端涿郡与余杭；贞观是太宗、开元是玄宗前期。", "唐由盛转衰看755安史之乱：节度使、外重内轻、藩镇割据。"], "vsum": "第6课是盛与衰的一课两面：581年隋建立、589年统一全国，开通以洛阳为中心的**大运河**；618年唐建立后，经**贞观之治**到**开元盛世**，==民族交融与对外开放达到高峰==。但节度使坐大、外重内轻酿成755年安史之乱，唐由盛转衰、**藩镇割据**，875年黄巢起义再予重击，907年朱温灭唐，进入五代十国分裂时期。视频为源史社会纲要上第6课精讲（58:31）。\n易错提醒：隋朝大运河的中心是洛阳而不是长安，这是本课最常被记错的一点。", "vtech": ["看到大运河题 → 四点定位：中心、两端、沟通水系、影响（交流与统一为正、役重为负）。", "看到由盛转衰题 → 先找制度病根（节度使与外重内轻），再写事件（755）与后果（藩镇割据）。", "看到灭亡类问题 → 分清转折点与终结点：755是转折，907朱温灭唐才是终结。"], "vgaokao": []}}, "u_hist_7": {"id": "u_hist_7", "name": "隋唐制度的变化与创新", "secs": "第7课", "pageFrom": null, "pageTo": null, "members": ["hist_h013", "hist_h014"], "video": {"bvid": "BV1J9tHesEYa", "p": 1, "t": "第7课：隋唐制度的变化与创新", "dur": "31:46", "from": "小马历史课堂", "vtop": ["科举隋创唐完善，选官标准从门第转向考试；三省分工：中书出令、门下审令、尚书行令。", "租庸调以人丁为本（租粮、调绢布、庸力役），两税法以资产土地为本。", "780年两税法是赋税史转折：杨炎建议、德宗实行、夏秋两征。"], "vsum": "第7课讲两项长命制度与一次赋税大变：选官上，隋创**科举**（炀帝设进士科）、唐完善，打破门第垄断；中枢上，**三省六部制**以中书出令、门下审令、尚书执行、六部分工，既提效率又分相权、强皇权。赋税上，唐前期**租庸调制**以人丁为本，均田制破坏后难以为继，780年杨炎==两税法改以资产与土地为主要依据==、夏秋两征，影响此后近千年。视频为小马历史课堂纲要上第7课精讲（31:46，本站自存版），内容覆盖隋唐部分：科举、三省六部与两税法；宋朝分割相权一节视频未涵盖，看本站正文节点。\n易错提醒：科举制是隋朝创立、唐朝完善的，把它说成唐朝创立是最常见的丢分点。", "vtech": ["看到选官题 → 先问标准：推荐看门第还是考试定去取，一秒定制度名。", "看到三省题 → 按流程答：谁起草、谁审核、谁执行，顺序不能乱。", "看到赋税题 → 先比标准（人丁还是资产土地），再比次数与时间，780年是题眼。"], "vgaokao": []}}, "u_hist_8": {"id": "u_hist_8", "name": "三国至隋唐的文化", "secs": "第8课", "pageFrom": null, "pageTo": null, "members": ["hist_h015", "hist_h016"], "video": {"bvid": "BV1nV411w71C", "p": 1, "t": "第8课：三国至隋唐的文化（源史社会）", "dur": "34:42", "from": 0, "vtop": ["思想格局是三教并行、儒学为正统，韩愈在唐中期复兴儒学。", "科技只钉唐朝两项发明：雕版印刷与火药；《唐本草》是世界第一部国家药典。", "交流记方向：遣唐使来学、玄奘西行、鉴真东渡。"], "vsum": "第8课是文化总览：思想上儒学受佛道挑战、隋唐**三教并行**，韩愈复兴儒学；科技上唐朝出现**雕版印刷**与火药（唐末用于战争），**《唐本草》**为世界第一部国家药典，赵州桥为建筑典范。文学艺术上唐诗（李白、杜甫、白居易）、书法（颜真卿、柳公权）、绘画（吴道子）与敦煌莫高窟熠熠生辉；对外交流上遣唐使来学、==玄奘西行取经、鉴真东渡传法==，尽显开放气象。视频为源史社会纲要上第8课精讲（34:42）。\n易错提醒：玄奘是西行去天竺取经、鉴真是东渡去日本传法，两个人的方向千万别记反。", "vtech": ["看到文化成就题 → 先分门类（思想/科技/文学/书画/交流）再对人物作品，防张冠李戴。", "看到交流题 → 先定方向（来学、西行、东渡）再答内容与影响。", "看到首创之最题 → 核对时代：《唐本草》唐、活字印刷宋、《本草纲目》明，跨代即错。"], "vgaokao": []}}}, "nodeUnit": {"hist_h001": "u_hist_1", "hist_h002": "u_hist_1", "hist_h003": "u_hist_2", "hist_h004": "u_hist_2", "hist_h005": "u_hist_3", "hist_h006": "u_hist_3", "hist_h007": "u_hist_4", "hist_h008": "u_hist_4", "hist_h009": "u_hist_5", "hist_h010": "u_hist_5", "hist_h011": "u_hist_6", "hist_h012": "u_hist_6", "hist_h013": "u_hist_7", "hist_h014": "u_hist_7", "hist_h015": "u_hist_8", "hist_h016": "u_hist_8"}};

window.SELF_VIDEO_PACKS=(window.SELF_VIDEO_PACKS||[]);window.SELF_VIDEO_PACKS.push({"BV1J9tHesEYa|1": {"src": "/video/hist7.mp4", "vtt": "/video/hist7.vtt", "segs": [[0, "开场：穿越古代当皇帝，制度为什么要改"], [164, "三大创新总览：选官、赋税、中央官制"], [288, "选官简史：察举制与九品中正制"], [456, "科举诞生：隋文帝废九品中正、分科取士"], [617, "科举的影响与局限"], [785, "三省六部：先看秦朝三公九卿怎么分工"], [987, "三省六部流程：中书起草、门下审核、尚书执行"], [1150, "政事堂与宰相通货膨胀：相权被稀释"], [1314, "赋税简史：租、庸、调各是什么"], [1561, "均田制瓦解：土地兼并、失地农民"], [1601, "两税法：杨炎改革，按亩征税、一年两征"], [1805, "两税法的评价与历史局限"]]}});
